-- WhatsApp-style colours. Colour KOReader builds (Kaleido) show them as-is;
-- grayscale builds convert them automatically. Named gray fallbacks cover
-- very old builds that lack colour support.
local WA = {}
do
    local function color(hex, fallback)
        if Blitbuffer.colorFromString then
            local ok, value = pcall(Blitbuffer.colorFromString, hex)
            if ok and value then return value end
        end
        if Blitbuffer.ColorRGB32 then
            local r, g, b = hex:match("^#(%x%x)(%x%x)(%x%x)$")
            if r then
                local ok, value = pcall(Blitbuffer.ColorRGB32, tonumber(r, 16), tonumber(g, 16), tonumber(b, 16), 0xFF)
                if ok and value then return value end
            end
        end
        return fallback
    end
    WA.color = color
    WA.white = Blitbuffer.COLOR_WHITE
    WA.header = color("#008069", Blitbuffer.COLOR_GRAY_8)
    WA.header_sub = color("#CFE6E1", Blitbuffer.COLOR_LIGHT_GRAY)
    WA.wallpaper = color("#EFEAE2", Blitbuffer.COLOR_LIGHT_GRAY)
    WA.own = color("#D9FDD3", Blitbuffer.COLOR_LIGHT_GRAY)
    WA.other = Blitbuffer.COLOR_WHITE
    WA.text = color("#111B21", Blitbuffer.COLOR_BLACK)
    WA.sub = color("#667781", Blitbuffer.COLOR_DARK_GRAY)
    WA.tick_read = color("#34B7F1", Blitbuffer.COLOR_DARK_GRAY)
    WA.send = color("#00A884", Blitbuffer.COLOR_GRAY_8)
    WA.badge = color("#25D366", Blitbuffer.COLOR_GRAY_8)
    WA.divider = color("#E9EDEF", Blitbuffer.COLOR_LIGHT_GRAY)
    WA.selected = color("#F0F2F5", Blitbuffer.COLOR_LIGHT_GRAY)
    WA.panel = color("#F0F2F5", Blitbuffer.COLOR_LIGHT_GRAY)
    WA.pill = Blitbuffer.COLOR_WHITE
    WA.quote_own = color("#C5EDBD", Blitbuffer.COLOR_LIGHT_GRAY)
    WA.quote_other = color("#F0F2F5", Blitbuffer.COLOR_LIGHT_GRAY)
end

-- DChat always uses the WhatsApp palette (the AppDock theme palette is kept
-- only as `base` for anything that still wants it).
local function themePalette(context)
    return {
        background = WA.wallpaper, surface = WA.other, surface_variant = WA.divider,
        primary = WA.header, on_primary = WA.white,
        secondary = WA.header, on_secondary = WA.white,
        tertiary = WA.send, on_tertiary = WA.white,
        on_surface = WA.text, on_variant = WA.sub, outline = WA.divider,
        base = paletteFor(context),
    }
end

local DCHAT_SOURCE_DIR = (debug.getinfo(1, "S").source:sub(2):match("(.*/)") or "")

local function showInputDialog(dialog)
    if AppDockKeyboard then pcall(AppDockKeyboard.attach, dialog) end
    UIManager:show(dialog)
    if dialog.onShowKeyboard then dialog:onShowKeyboard() end
    return dialog
end

local function scale(value)
    return Device.screen:scaleBySize(value)
end

local function isAndroidDevice()
    return type(Device.isAndroid) == "function" and Device:isAndroid() == true
end

local function safeImageWidget(options)
    local loaded, ImageWidget = pcall(require, "ui/widget/imagewidget")
    if not loaded or not ImageWidget then return nil end
    -- DM images are user-supplied and can be much larger when decoded than on the wire.
    -- Keep them out of KOReader's small shared ImageWidget cache.
    options.file_do_cache = false
    local ok, widget = pcall(function() return ImageWidget:new(options) end)
    return ok and widget or nil
end

local function clearAttachmentFiles(state)
    if type(state.attachment_files) == "table" then
        for _, path in pairs(state.attachment_files) do
            if type(path) == "string" then pcall(os.remove, path) end
        end
    end
    state.attachment_files = {}
end

local function ensureAttachmentCacheDir()
    local ok, attr = pcall(lfs.attributes, ATTACHMENT_CACHE_DIR)
    if ok and attr and attr.mode == "directory" then return true end
    local made_ok, made = pcall(lfs.mkdir, ATTACHMENT_CACHE_DIR)
    if made_ok and made then return true end
    local check_ok, check = pcall(lfs.attributes, ATTACHMENT_CACHE_DIR)
    return check_ok and check ~= nil and check.mode == "directory"
end

local function prepareAttachmentCache(state)
    if attachment_cache_prepared then return end
    clearAttachmentFiles(state)
    if ensureAttachmentCacheDir() then
        local ok, iterator, directory, initial = pcall(lfs.dir, ATTACHMENT_CACHE_DIR)
        if ok and type(iterator) == "function" then
            for name in iterator, directory, initial do
                if type(name) == "string" and name:match("^dchat_[%w_%-]+_%d+%.[%w]+$") then
                    pcall(os.remove, ATTACHMENT_CACHE_DIR .. "/" .. name)
                end
            end
        end
    end
    attachment_cache_prepared = true
end

local function trim(value)
    if type(value) ~= "string" then return "" end
    return value:match("^%s*(.-)%s*$") or ""
end

local function emptySizedWidget(width, height)
    return CenterContainer:new{ dimen = Geom:new{ w = width, h = height }, HorizontalSpan:new{ width = 0 } }
end

local function safeText(value, maximum)
    value = trim(value):gsub("[%c]", " "):gsub("%s+", " ")
    if value == "" or #value > maximum then return nil end
    return value
end

local function imageMimeForPath(path)
    local lower = tostring(path or ""):lower()
    if lower:match("%.png$") then return "image/png" end
    if lower:match("%.jpg$") or lower:match("%.jpeg$") then return "image/jpeg" end
    if lower:match("%.gif$") then return "image/gif" end
    if lower:match("%.webp$") then return "image/webp" end
end

local function cloneMessage(raw)
    if type(raw) ~= "table" then return nil end
    local id = trim(tostring(raw.id or ""))
    local author_name = safeText(raw.authorName, MAX_NAME_BYTES)
    local body = safeText(raw.body, MAX_TEXT_BYTES)
    local created_at = trim(tostring(raw.createdAt or "")):sub(1, 48)
    if not id:match("^%d+$") or not author_name or not body then return nil end
    return { id = id, authorName = author_name, body = body, createdAt = created_at }
end

local function cloneRecipient(raw)
    if type(raw) ~= "table" then return nil end
    local device_id = trim(raw.deviceId):sub(1, 64)
    local display_name = safeText(raw.displayName, MAX_NAME_BYTES)
    if not device_id:match("^dch_[%w_%-]+$") or not display_name then return nil end
    return { deviceId = device_id, displayName = display_name, unreadCount = tonumber(raw.unreadCount) or 0 }
end

local function cloneDirectMessage(raw)
    if type(raw) ~= "table" then return nil end
    local id = trim(tostring(raw.id or ""))
    local author_name = safeText(raw.authorName, MAX_NAME_BYTES)
    local body = safeText(raw.body or "", MAX_TEXT_BYTES) or ""
    local created_at = trim(tostring(raw.createdAt or "")):sub(1, 48)
    local attachment_mime = trim(tostring(raw.attachmentMime or ""))
    local attachment_data = trim(tostring(raw.attachmentData or ""))
    if #attachment_data > MAX_ATTACHMENT_BASE64_BYTES then
        local notice = _("[Image attachment omitted: larger than the 512 KiB DChat limit]")
        body = body == "" and notice or body:sub(1, math.max(0, MAX_TEXT_BYTES - #notice)) .. notice
        attachment_data, attachment_mime = "", ""
    end
    if not id:match("^%d+$") or not author_name or (body == "" and attachment_data == "") then return nil end
    return { id = id, authorName = author_name, body = body, createdAt = created_at, senderDeviceId = trim(tostring(raw.senderDeviceId or "")), readAt = trim(tostring(raw.readAt or "")), attachmentMime = attachment_mime, attachmentData = attachment_data }
end

local function cloneStore(raw)
    raw = type(raw) == "table" and raw or {}
    local messages, seen = {}, {}
    local recipients, recipient_seen = {}, {}
    local dm_messages, dm_seen = {}, {}
    local hidden_recipient_ids, hidden_seen = {}, {}
    for _, raw_id in ipairs(type(raw.hidden_recipient_ids) == "table" and raw.hidden_recipient_ids or {}) do
        local device_id = trim(tostring(raw_id or ""))
        if device_id:match("^dch_[%w_%-]+$") and not hidden_seen[device_id] and #hidden_recipient_ids < MAX_RECIPIENTS then
            hidden_seen[device_id] = true
            hidden_recipient_ids[#hidden_recipient_ids + 1] = device_id
        end
    end
    for index, raw_message in ipairs(type(raw.messages) == "table" and raw.messages or {}) do
        local message = cloneMessage(raw_message)
        if message and not seen[message.id] and #messages < MAX_CACHE_MESSAGES then
            seen[message.id] = true
            messages[#messages + 1] = message
        end
    end
    for index, raw_recipient in ipairs(type(raw.recipients) == "table" and raw.recipients or {}) do
        local recipient = cloneRecipient(raw_recipient)
        if recipient and recipient.deviceId ~= raw.device_id and not hidden_seen[recipient.deviceId] and not recipient_seen[recipient.deviceId] and #recipients < MAX_RECIPIENTS then
            recipient_seen[recipient.deviceId] = true
            recipients[#recipients + 1] = recipient
        end
    end
    for index, raw_dm_message in ipairs(type(raw.dm_messages) == "table" and raw.dm_messages or {}) do
        local message = cloneDirectMessage(raw_dm_message)
        if message and not dm_seen[message.id] and #dm_messages < MAX_CACHE_MESSAGES then
            dm_seen[message.id] = true
            dm_messages[#dm_messages + 1] = message
        end
    end
    local saved_endpoint = trim(raw.endpoint):gsub("/+$", "")
    if saved_endpoint == "" then saved_endpoint = DEFAULT_ENDPOINT end
    local saved_dm_endpoint = trim(raw.dm_endpoint):gsub("/+$", "")
    if saved_dm_endpoint == "" or saved_dm_endpoint == LEGACY_DM_ENDPOINT or saved_dm_endpoint == LEGACY_ENDPOINT then saved_dm_endpoint = DEFAULT_DM_ENDPOINT end
    return {
        endpoint = saved_endpoint:gsub("/+$", ""):sub(1, MAX_ENDPOINT_BYTES),
        dm_endpoint = saved_dm_endpoint:sub(1, MAX_ENDPOINT_BYTES),
        device_id = trim(raw.device_id):sub(1, 52),
        device_secret = trim(raw.device_secret):sub(1, 128),
        display_name = safeText(raw.display_name, MAX_NAME_BYTES) or "",
        messages = messages,
        recipients = recipients,
        hidden_recipient_ids = hidden_recipient_ids,
        dm_messages = dm_messages,
        selected_recipient_id = trim(raw.selected_recipient_id):match("^dch_[%w_%-]+$") and trim(raw.selected_recipient_id) or "",
        selected_recipient_name = safeText(raw.selected_recipient_name, MAX_NAME_BYTES) or "",
        last_refresh = tonumber(raw.last_refresh) or 0,
        last_background_check = math.max(0, math.floor(tonumber(raw.last_background_check) or 0)),
        last_seen_message_id = trim(raw.last_seen_message_id):match("^%d+$") and trim(raw.last_seen_message_id) or "",
        background_baseline_ready = raw.background_baseline_ready == true,
    }
end

local function tbsDisplayName()
    local settings = G_reader_settings:readSetting("appdock_homescreen", {})
    local account = type(settings) == "table" and settings.tbs_account or nil
    if type(account) == "table" and account.enabled == true then
        local name = safeText(account.display_name or account.username, MAX_NAME_BYTES)
        if name then return name end
    end
    return ""
end

local function loadStore()
    local store = cloneStore(G_reader_settings:readSetting(SETTINGS_KEY, {}))
    -- A TBS profile is optional. Existing DChat identities always win; a new
    -- identity created from DChat will use the TBS public name as its handle.
    if store.display_name == "" then store.display_name = tbsDisplayName() end
    return store
end

local function saveStore(store)
    G_reader_settings:saveSetting(SETTINGS_KEY, cloneStore(store))
end

local function validEndpoint(value)
    value = trim(value):gsub("/+$", "")
    if value == "" or #value > MAX_ENDPOINT_BYTES or value:find("[%c%s]") then return nil, _("Enter the HTTPS address of the public DChat service.") end
    local ok, socket_url = pcall(require, "socket.url")
    if not ok or not socket_url then return nil, _("URL support is unavailable.") end
    local parsed = socket_url.parse(value)
    if not parsed or parsed.scheme ~= "https" or not parsed.host or parsed.host == "" or parsed.userinfo or parsed.query or parsed.fragment then
        return nil, _("Use a valid HTTPS service address without login, query or fragment.")
    end
    return value
end

local function hasIdentity(store)
    return store.device_id:match("^dch_[%w_%-]+$") and store.device_secret:match("^[%w_%-]+$") and store.display_name ~= ""
end

local function randomHex(bytes)
    local file = io.open("/dev/urandom", "rb")
    if not file then return nil end
    local data = file:read(bytes)
    file:close()
    if type(data) ~= "string" or #data ~= bytes then return nil end
    return (data:gsub(".", function(character) return string.format("%02x", string.byte(character)) end))
end

local function newIdentity()
    local public_part, secret_part = randomHex(12), randomHex(24)
    if not public_part or not secret_part then return nil, _("The reader could not create a secure local device identity.") end
    return "dch_" .. public_part, secret_part
end

local function apiUrl(store, suffix, endpoint_override)
    local endpoint, err = validEndpoint(endpoint_override or store.endpoint)
    if not endpoint then return nil, err end
    return endpoint .. "/api/dchat/v1" .. suffix
end

local function httpJson(store, method, suffix, payload, include_identity, endpoint_override)
    local url, url_err = apiUrl(store, suffix, endpoint_override)
    if not url then return nil, nil, url_err end
    local ok_https, https = pcall(require, "ssl.https")
    local ok_socket, socket = pcall(require, "socket")
    local ok_ltn12, ltn12 = pcall(require, "ltn12")
    local ok_util, socketutil = pcall(require, "socketutil")
    local ok_json, JSON = pcall(require, "json")
    if not ok_https or not ok_socket or not ok_ltn12 or not ok_util or not ok_json then return nil, nil, _("HTTPS or JSON support is unavailable.") end
    local chunks, received = {}, 0
    local function sink(chunk, sink_err)
        if sink_err then return nil, sink_err end
        if chunk then
            received = received + #chunk
            if received > MAX_RESPONSE_BYTES then return nil, RESPONSE_TOO_LARGE end
            chunks[#chunks + 1] = chunk
        end
        return 1
    end
    local headers = { ["accept"] = "application/json", ["user-agent"] = "AppDock-DChat/1.1" }
    -- Only Supabase DM calls need the publishable API key. Public DChat stays on Manus.
    local request_endpoint = trim(endpoint_override or "")
    if request_endpoint:find("qndwbriqomqqaqhkasbh%.supabase%.co/functions/v1/quick%-endpoint") then
        if SUPABASE_DM_PUBLISHABLE_KEY == "" or SUPABASE_DM_PUBLISHABLE_KEY == "PASTE_YOUR_SB_PUBLISHABLE_KEY_HERE" then
            return nil, nil, _("Set the Supabase publishable key in dchat.lua before testing DMs.")
        end
        headers["apikey"] = SUPABASE_DM_PUBLISHABLE_KEY
    end
    local body = nil
    if payload then
        local encoded_ok, encoded = pcall(JSON.encode, payload)
        if not encoded_ok or type(encoded) ~= "string" or #encoded > MAX_RESPONSE_BYTES then return nil, nil, _("The DChat request could not be encoded.") end
        body = encoded
        headers["content-type"] = "application/json"
        headers["content-length"] = tostring(#body)
    end
    if include_identity then
        if not hasIdentity(store) then return nil, nil, _("Create a local DChat identity first.") end
        headers["x-dchat-device-id"] = store.device_id
        headers["x-dchat-device-secret"] = store.device_secret
    end
    -- Match AppDock's established KOReader HTTPS transport. KOReader's LuaSec
    -- bundle owns TLS/SNI behavior; forcing a separate CA mode here can fail on
    -- readers that do not ship a system CA bundle.
    local request = { url = url, method = method, sink = sink, headers = headers }
    if body then request.source = ltn12.source.string(body) end
    socketutil:set_timeout(CONNECT_TIMEOUT, REQUEST_MAX_TIME)
    local ok, code, response_headers, status = pcall(function() return socket.skip(1, https.request(request)) end)
    socketutil:reset_timeout()
    code = tonumber(code)
    local response_body = table.concat(chunks)
    local decoded = nil
    if response_body ~= "" then
        local decoded_ok, result = pcall(JSON.decode, response_body, JSON.decode.simple)
        if decoded_ok and type(result) == "table" then decoded = result end
    end
    if not ok or not response_headers then
        if status == RESPONSE_TOO_LARGE then return nil, nil, RESPONSE_TOO_LARGE end
        local detail = safeText(tostring(status or code or ""), 160)
        local message = _("DChat could not reach the service. Your saved messages remain on this reader.")
        if detail and detail ~= "" then message = message .. " " .. detail end
        return nil, nil, message
    end
    if not code then return nil, nil, _("DChat could not reach the service. Your saved messages remain on this reader.") end
    if code < 200 or code > 299 then
        local message = decoded and decoded.error and safeText(decoded.error.message, 240)
        return nil, code, message or _("The DChat service refused the request.")
    end
    if not decoded then return nil, code, _("The DChat service returned invalid data.") end
    return decoded, code
end

local function replaceMessages(store, raw_messages)
    local messages, seen = {}, {}
    for index, raw_message in ipairs(type(raw_messages) == "table" and raw_messages or {}) do
        local message = cloneMessage(raw_message)
        if message and not seen[message.id] and #messages < MAX_CACHE_MESSAGES then
            seen[message.id] = true
            messages[#messages + 1] = message
        end
    end
    store.messages = messages
    store.last_refresh = os.time()
end

local function hiddenRecipientSet(store)
    local hidden = {}
    for _, raw_id in ipairs(type(store and store.hidden_recipient_ids) == "table" and store.hidden_recipient_ids or {}) do
        local device_id = trim(tostring(raw_id or ""))
        if device_id:match("^dch_[%w_%-]+$") then hidden[device_id] = true end
    end
    return hidden
end

local function replaceRecipients(store, raw_recipients)
    local recipients, seen = {}, {}
    local hidden = hiddenRecipientSet(store)
    for _, raw_recipient in ipairs(type(raw_recipients) == "table" and raw_recipients or {}) do
        local recipient = cloneRecipient(raw_recipient)
        if recipient and recipient.deviceId ~= store.device_id and not hidden[recipient.deviceId] and not seen[recipient.deviceId] and #recipients < MAX_RECIPIENTS then
            seen[recipient.deviceId] = true
            recipients[#recipients + 1] = recipient
        end
    end
    store.recipients = recipients
end

local function mergeRecipients(store, raw_recipients)
    local combined = {}
    for _, recipient in ipairs(type(store and store.recipients) == "table" and store.recipients or {}) do
        combined[#combined + 1] = recipient
    end
    for _, recipient in ipairs(type(raw_recipients) == "table" and raw_recipients or {}) do
        combined[#combined + 1] = recipient
    end
    replaceRecipients(store, combined)
end

local function replaceDirectMessages(store, raw_messages)
    local messages, seen = {}, {}
    for _, raw_message in ipairs(type(raw_messages) == "table" and raw_messages or {}) do
        local message = cloneDirectMessage(raw_message)
        if message and not seen[message.id] and #messages < MAX_CACHE_MESSAGES then
            seen[message.id] = true
            messages[#messages + 1] = message
        end
    end
    store.dm_messages = messages
end

local function urlEncode(value)
    return tostring(value):gsub("([^%w%-_%.~])", function(character) return string.format("%%%02X", string.byte(character)) end)
end

local function base64Encode(data)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local output = {}
    for index = 1, #data, 3 do
        local a, b, c = data:byte(index, index + 2)
        local n = a * 65536 + (b or 0) * 256 + (c or 0)
        output[#output + 1] = alphabet:sub(math.floor(n / 262144) % 64 + 1, math.floor(n / 262144) % 64 + 1)
            .. alphabet:sub(math.floor(n / 4096) % 64 + 1, math.floor(n / 4096) % 64 + 1)
            .. (b and alphabet:sub(math.floor(n / 64) % 64 + 1, math.floor(n / 64) % 64 + 1) or "=")
            .. (c and alphabet:sub(n % 64 + 1, n % 64 + 1) or "=")
    end
    return table.concat(output)
end

local function base64Decode(data)
    if type(data) ~= "string" then return nil end
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local decoded = {}
    data = data:gsub("%s", "")
    if data == "" or #data % 4 ~= 0 or data:find("[^%w%+/=]") or (data:find("=", 1, true) and not (data:match("^[%w%+/]+=$") or data:match("^[%w%+/]+==$"))) then return nil end
    for index = 1, #data, 4 do
        local a, b, c, d = data:sub(index, index + 3):match("^(%S)(%S)(%S)(%S)$")
        local va, vb = alphabet:find(a, 1, true), alphabet:find(b, 1, true)
        if not va or not vb then return nil end
        local vc = c == "=" and 0 or (alphabet:find(c, 1, true) or 0) - 1
        local vd = d == "=" and 0 or (alphabet:find(d, 1, true) or 0) - 1
        if not vc or not vd then return nil end
        local n = (va - 1) * 262144 + (vb - 1) * 4096 + vc * 64 + vd
        decoded[#decoded + 1] = string.char(math.floor(n / 65536) % 256)
        if c ~= "=" then decoded[#decoded + 1] = string.char(math.floor(n / 256) % 256) end
        if d ~= "=" then decoded[#decoded + 1] = string.char(n % 256) end
    end
    return table.concat(decoded)
end

local function newestMessageId(messages)
    local newest_id, newest_number = "", -1
    for _, message in ipairs(messages or {}) do
        local numeric_id = tonumber(message.id)
        if numeric_id and numeric_id > newest_number then newest_id, newest_number = message.id, numeric_id end
    end
    return newest_id, newest_number
end

local function markMessagesSeen(store)
    local newest_id = newestMessageId(store.messages)
    if newest_id ~= "" then store.last_seen_message_id = newest_id end
    store.background_baseline_ready = true
end

local function countNewMessages(messages, last_seen_message_id)
    local seen_number = tonumber(last_seen_message_id)
    if not seen_number then return 0 end
    local count = 0
    for _, message in ipairs(messages or {}) do
        local numeric_id = tonumber(message.id)
        if numeric_id and numeric_id > seen_number then count = count + 1 end
    end
    return count
end

local function wifiIsOn()
    local loaded, NetworkMgr = pcall(require, "ui/network/manager")
    if not loaded or not NetworkMgr or type(NetworkMgr.isWifiOn) ~= "function" then return false end
    local state_ok, wifi_on = pcall(NetworkMgr.isWifiOn, NetworkMgr)
    return state_ok and wifi_on == true
end

local function stateFor(instance)
    instance.dchat = instance.dchat or { store = loadStore(), view = "dm", compact_sidebar = true, emoji_open = false, emoji_page = 1, page = 1, dm_page = 1, recipient_page = 1, public_scroll = 0, dm_scroll = 0, recipient_scroll = 0, public_draft = "", draft_text = "", selected_id = nil, selected_dm_id = nil, status = _("Public DChat service ready. Create a local identity before posting or reporting."), loading = false, attachment_files = {} }
    prepareAttachmentCache(instance.dchat)
    return instance.dchat
end

local function refresh(context)
    context.requestRebuild("ui")
end

local function setEndpoint(state, context)
    local dialog
    dialog = InputDialog:new{
        title = _("Public DChat service"), input = state.store.endpoint, input_hint = "https://dchat.example.org",
        buttons = { { { text = _("Cancel"), callback = function() UIManager:close(dialog) end }, { text = _("Save"), is_enter_default = true, callback = function()
            local endpoint, err = validEndpoint(dialog:getInputText())
            if not endpoint then state.status = err; UIManager:close(dialog); refresh(context); return end
            state.store.endpoint = endpoint
            state.store.last_background_check, state.store.last_seen_message_id, state.store.background_baseline_ready = 0, "", false
            saveStore(state.store)
            state.status = _("Public service address saved locally. Create an identity before posting or reporting.")
            UIManager:close(dialog)
            refresh(context)
        end } } },
    }
    showInputDialog(dialog)
end

local function setDMEndpoint(state, context)
    local dialog
    dialog = InputDialog:new{
        title = _("Private DM service"), input = state.store.dm_endpoint, input_hint = "https://dchatdm.example.org",
        buttons = { { { text = _("Cancel"), callback = function() UIManager:close(dialog) end }, { text = _("Save"), is_enter_default = true, callback = function()
            local endpoint, err = validEndpoint(dialog:getInputText())
            if not endpoint then state.status = err; UIManager:close(dialog); refresh(context); return end
            state.store.dm_endpoint = endpoint
            saveStore(state.store)
            state.status = _("DM service address saved locally.")
            UIManager:close(dialog)
            refresh(context)
        end } } },
    }
    showInputDialog(dialog)
end

local function registerIdentity(state, context, display_name)
    local name = safeText(display_name, MAX_NAME_BYTES)
    if not name or #name < 3 then state.status = _("Use a display name with 3–24 visible characters."); refresh(context); return end
    local device_id, device_secret = newIdentity()
    if not device_id then state.status = device_secret; refresh(context); return end
    local draft = cloneStore(state.store)
    draft.device_id, draft.device_secret, draft.display_name = device_id, device_secret, name
    local response, code, err = httpJson(draft, "POST", "/devices", { deviceId = device_id, deviceSecret = device_secret, displayName = name }, false)
    if not response then
        state.status = err or _("DChat identity registration failed.")
        refresh(context)
        return
    end
    local dm_response = httpJson(draft, "POST", "/devices", { deviceId = device_id, deviceSecret = device_secret, displayName = name }, false, draft.dm_endpoint)
    state.store.device_id, state.store.device_secret, state.store.display_name = device_id, device_secret, name
    saveStore(state.store)
    state.status = dm_response and _("Local DChat identity registered for public chat and DMs. This identity cannot be recovered after reset.") or _("Public identity registered; DMs will retry registration on first use.")
    refresh(context)
end

local function promptIdentity(state, context, reset)
    local dialog
    dialog = InputDialog:new{
        title = reset and _("Reset local identity") or _("Create local identity"), input = reset and "" or state.store.display_name, input_hint = _("Display name (3–24 characters)"),
        buttons = { { { text = _("Cancel"), callback = function() UIManager:close(dialog) end }, { text = _("Create"), is_enter_default = true, callback = function()
            local name = dialog:getInputText()
            UIManager:close(dialog)
            registerIdentity(state, context, name)
        end } } },
    }
    showInputDialog(dialog)
end

local function createOrResetIdentity(state, context)
    if not hasIdentity(state.store) then promptIdentity(state, context, false); return end
    UIManager:show(ConfirmBox:new{
        text = _("Reset this reader's DChat identity?\n\nThe current local device secret cannot be recovered or transferred. You will lose the ability to act as this identity. Public messages already posted remain public."),
        ok_text = _("Reset identity"),
        ok_callback = function() promptIdentity(state, context, true) end,
    })
end

local function deleteIdentity(state, context)
    if not hasIdentity(state.store) then
        state.status = _("No local DChat identity to delete.")
        refresh(context)
        return
    end
    local public_response, _, public_err = httpJson(state.store, "DELETE", "/devices", nil, true)
    local dm_response, _, dm_err = httpJson(state.store, "DELETE", "/devices", nil, true, state.store.dm_endpoint)
    if not public_response and not dm_response then
        state.status = public_err or dm_err or _("The DChat account could not be deleted.")
        refresh(context)
        return
    end
    local partial = not public_response or not dm_response
    state.store.device_id, state.store.device_secret, state.store.display_name = "", "", ""
    state.store.recipients, state.store.hidden_recipient_ids, state.store.dm_messages = {}, {}, {}
    state.store.selected_recipient_id, state.store.selected_recipient_name = "", ""
    state.recipient_page, state.dm_page, state.view = 1, 1, "settings"
    saveStore(state.store)
    state.status = partial and _("The account was deleted from one service; the other service could not be reached.") or _("DChat account deleted. Public messages already posted remain public.")
    refresh(context)
end

local function confirmDeleteIdentity(state, context)
    UIManager:show(ConfirmBox:new{
        text = _("Delete this DChat account from the public and private services? This removes the account and its server data and cannot be undone. Public messages already posted remain public."),
        ok_text = _("Delete account"),
        ok_callback = function() deleteIdentity(state, context) end,
    })
end

local function fetchMessages(state, context)
    if state.loading then return end
    state.loading = true
    state.status = _("Refreshing public messages…")
    refresh(context)
    local response, code, err = httpJson(state.store, "GET", "/messages?limit=" .. tostring(MAX_CACHE_MESSAGES), nil, false)
    state.loading = false
    if not response or type(response.messages) ~= "table" then
        state.status = err or _("DChat refresh failed. The previous local cache is still shown.")
        refresh(context)
        return
    end
    replaceMessages(state.store, response.messages)
    markMessagesSeen(state.store)
    state.page, state.public_scroll = 1, 0
    saveStore(state.store)
    state.status = #state.store.messages == 0 and _("No public messages yet.") or _("Public messages refreshed manually.")
    refresh(context)
end

local function applyBackgroundResult(instance, context, result)
    local state = stateFor(instance)
    if type(result) ~= "table" or result.kind ~= "dchat_messages" then return false end
    local response = result.response
    if type(response) ~= "table" or type(response.messages) ~= "table" then
        saveStore(state.store)
        return false
    end
    local previous_seen = state.store.last_seen_message_id
    replaceMessages(state.store, response.messages)
    local newest_id = newestMessageId(state.store.messages)
    if not state.store.background_baseline_ready then
        state.store.last_seen_message_id = newest_id
        state.store.background_baseline_ready = true
        saveStore(state.store)
        return true
    end
    local new_count = previous_seen == "" and #state.store.messages or countNewMessages(state.store.messages, previous_seen)
    state.store.last_seen_message_id = newest_id ~= "" and newest_id or previous_seen
    saveStore(state.store)
    if new_count > 0 and context and type(context.notify) == "function" then
        pcall(context.notify, {
            title = _("DChat"),
            message = new_count == 1 and _("1 new public message in AppDock Lounge.") or string.format(_("%d new public messages in AppDock Lounge."), new_count),
            source = "DChat",
            priority = "normal",
        })
        return true
    end
    return true
end

local function backgroundCheck(instance, context)
    local state = stateFor(instance)
    local now = math.max(0, math.floor(tonumber(context and context.now) or os.time()))
    if now - state.store.last_background_check < BACKGROUND_CHECK_SECONDS then return { kind = "dchat_messages", skipped = "interval" } end
    if not wifiIsOn() then return { kind = "dchat_messages", skipped = "wifi" } end
    state.store.last_background_check = now
    local response, code, err = httpJson(state.store, "GET", "/messages?limit=" .. tostring(MAX_CACHE_MESSAGES), nil, false)
    if context and context.subprocess then
        return { kind = "dchat_messages", response = response, code = code, error = err }
    end
    return applyBackgroundResult(instance, context, { kind = "dchat_messages", response = response, code = code, error = err })
end

local function sendMessage(state, context, text)
    local message = safeText(text, MAX_TEXT_BYTES)
    if not message or #message > 500 then state.status = _("Use a plain-text message between 1 and 500 characters."); refresh(context); return end
    local response, code, err = httpJson(state.store, "POST", "/messages", { text = message }, true)
    if not response then state.status = err or _("Message could not be sent."); refresh(context); return end
    state.public_draft = ""
    state.status = _("Message sent publicly. DChat has no private messages or encryption.")
    fetchMessages(state, context)
end

local function promptMessage(state, context)
    if not hasIdentity(state.store) then state.status = _("Create a local identity before sending a public message."); refresh(context); return end
    local dialog
    dialog = InputDialog:new{
        title = _("Public message"), input = state.public_draft or "", input_hint = _("Plain text, up to 500 characters"),
        buttons = { { { text = _("Cancel"), callback = function() UIManager:close(dialog) end }, { text = _("Save draft"), callback = function()
            local text = safeText(dialog:getInputText(), MAX_TEXT_BYTES)
            UIManager:close(dialog)
            if not text or #text > 500 then state.status = _("Use a plain-text message between 1 and 500 characters."); refresh(context); return end
            state.public_draft = text
            state.status = _("Public message draft saved.")
            refresh(context)
        end }, { text = _("Send"), is_enter_default = true, callback = function()
            local text = dialog:getInputText()
            UIManager:close(dialog)
            sendMessage(state, context, text)
        end } } },
    }
    showInputDialog(dialog)
end

local function selectedRecipient(state)
    for _, recipient in ipairs(state.store.recipients or {}) do
        if recipient.deviceId == state.store.selected_recipient_id then return recipient end
    end
end

local function registerExistingIdentity(state)
    if not hasIdentity(state.store) then return false end
    local response = httpJson(state.store, "POST", "/devices", {
        deviceId = state.store.device_id,
        deviceSecret = state.store.device_secret,
        displayName = state.store.display_name,
    }, false, state.store.dm_endpoint)
    return response ~= nil
end

local function fetchRecipients(state, context, query)
    if state.loading then return end
    state.loading = true
    state.status = _("Searching DChat recipients…")
    refresh(context)
    local clean_query = trim(query or "")
    if #clean_query > MAX_NAME_BYTES then clean_query = clean_query:sub(1, MAX_NAME_BYTES) end
    local suffix = "/recipients?limit=" .. tostring(MAX_RECIPIENTS)
    if clean_query ~= "" then suffix = suffix .. "&q=" .. urlEncode(clean_query) end
    local response, code, err = httpJson(state.store, "GET", suffix, nil, true, state.store.dm_endpoint)
    if not response and code == 401 and registerExistingIdentity(state) then
        response, code, err = httpJson(state.store, "GET", suffix, nil, true, state.store.dm_endpoint)
    end
    state.loading = false
    if not response or type(response.recipients) ~= "table" then
        state.status = err or _("Recipient search failed.")
        refresh(context)
        return
    end
    if clean_query ~= "" then mergeRecipients(state.store, response.recipients) else replaceRecipients(state.store, response.recipients) end
    state.recipient_page, state.recipient_scroll = 1, 0
    saveStore(state.store)
    state.status = #state.store.recipients == 0 and _("No recipients found.") or _("Recipients refreshed manually.")
    refresh(context)
end

local function deferConversationRefresh(state, context)
    UIManager:tickAfterNext(function()
        if state.view == "dm_conversation" then refresh(context) end
    end)
end

local function fetchConversation(state, context)
    if state.loading or state.store.selected_recipient_id == "" then return end
    state.loading = true
    state.status = _("Refreshing private conversation…")
    local conversation_path = "/dms/" .. urlEncode(state.store.selected_recipient_id)
    local response, code, err = httpJson(state.store, "GET", conversation_path .. "?limit=" .. tostring(MAX_CACHE_MESSAGES), nil, true, state.store.dm_endpoint)
    if not response and err == RESPONSE_TOO_LARGE then
        response, code, err = httpJson(state.store, "GET", conversation_path .. "?limit=" .. tostring(CONVERSATION_RETRY_LIMIT), nil, true, state.store.dm_endpoint)
    end
    state.loading = false
    if not response or type(response.conversation) ~= "table" then
        state.status = err == RESPONSE_TOO_LARGE and _("This chat contains very large attachments. The latest messages could not be loaded; saved messages remain on this reader.") or (err or _("Private conversation could not be loaded."))
        deferConversationRefresh(state, context)
        return
    end
    state.store.selected_recipient_name = safeText(response.conversation.displayName, MAX_NAME_BYTES) or state.store.selected_recipient_name
    replaceDirectMessages(state.store, response.conversation.messages)
    state.dm_page = math.max(1, math.ceil(#state.store.dm_messages / MAX_VISIBLE_PER_PAGE))
    state.dm_scroll = 0
    saveStore(state.store)
    state.status = #state.store.dm_messages == 0 and _("No private messages yet.") or _("Private conversation refreshed.")
    deferConversationRefresh(state, context)
end

local function deleteConversation(state, context)
    if state.store.selected_recipient_id == "" then return end
    local response, code, err = httpJson(state.store, "DELETE", "/dms/" .. urlEncode(state.store.selected_recipient_id), nil, true, state.store.dm_endpoint)
    if not response or response.deleted ~= true then
        state.status = err or _("The private chat could not be deleted.")
        refresh(context)
        return
    end
    state.store.dm_messages = {}
    clearAttachmentFiles(state)
    state.store.selected_recipient_id = ""
    state.store.selected_recipient_name = ""
    state.selected_dm_id = nil
    state.dm_page = 1
    state.view = "dm"
    saveStore(state.store)
    state.status = _("Private chat deleted from the server.")
    refresh(context)
end

local function confirmDeleteConversation(state, context)
    UIManager:show(ConfirmBox:new{
        text = _("Delete this private chat and all server-stored messages for both participants? This cannot be undone."),
        ok_text = _("Delete chat"),
        ok_callback = function() deleteConversation(state, context) end,
    })
end

local function openPrivateChats(state, context)
    if not hasIdentity(state.store) then state.status = _("Create a local identity before opening private chats."); refresh(context); return end
    clearAttachmentFiles(state)
    state.view = "dm"
    fetchRecipients(state, context, "")
end

local function promptRecipientSearch(state, context)
    local dialog
    dialog = InputDialog:new{
        title = _("Find recipient"), input = "", input_hint = _("Display name or device ID"),
        buttons = { { { text = _("Cancel"), callback = function() UIManager:close(dialog) end }, { text = _("Search"), is_enter_default = true, callback = function() local query = dialog:getInputText(); UIManager:close(dialog); fetchRecipients(state, context, query) end } } },
    }
    showInputDialog(dialog)
end

local function sendDirectMessage(state, context, text, attachment)
    local recipient = selectedRecipient(state)
    local message = safeText(text, MAX_TEXT_BYTES)
    if not recipient or (not message and not attachment) then state.status = _("Choose a recipient and use text or a small image."); refresh(context); return end
    if recipient.deviceId == state.store.device_id then
        state.store.selected_recipient_id = ""
        state.store.selected_recipient_name = ""
        state.view = "dm"
        state.status = _("You cannot send a private message to this reader. Choose another recipient.")
        saveStore(state.store)
        refresh(context)
        return
    end
    local response, code, err = httpJson(state.store, "POST", "/dms", { recipientDeviceId = recipient.deviceId, text = message or "", attachment = attachment }, true, state.store.dm_endpoint)
    if not response then
        if code == 400 then
            state.store.selected_recipient_id = ""
            state.store.selected_recipient_name = ""
            state.view = "dm"
            state.status = _("This recipient is no longer available. The recipient list was refreshed.")
            saveStore(state.store)
            fetchRecipients(state, context, "")
            return
        end
        state.status = err or _("Private message could not be sent.")
        refresh(context)
        return
    end
    state.draft_text = ""
    state.status = _("Private message sent. It is stored server-side and is not end-to-end encrypted.")
    fetchConversation(state, context)
end

local function promptDirectMessage(state, context, initial_text)
    if not hasIdentity(state.store) then state.status = _("Create a local identity before sending a private message."); refresh(context); return end
    if not selectedRecipient(state) then state.status = _("Choose a recipient first."); refresh(context); return end
    local dialog
    dialog = InputDialog:new{
        title = _("Private message"), input = initial_text or state.draft_text or "", input_hint = _("Text or attached image, up to 1500 characters"),
        buttons = { { { text = _("Cancel"), callback = function() UIManager:close(dialog) end }, { text = _("Save draft"), callback = function()
            local text = safeText(dialog:getInputText(), MAX_TEXT_BYTES)
            UIManager:close(dialog)
            if not text then state.status = _("Use a plain-text message between 1 and 1500 characters."); refresh(context); return end
            state.draft_text = text
            state.status = _("Private message draft saved.")
            refresh(context)
        end }, { text = _("Send"), is_enter_default = true, callback = function() local text = dialog:getInputText(); UIManager:close(dialog); sendDirectMessage(state, context, text, nil) end } } },
    }
    showInputDialog(dialog)
end

local function selectedMessage(state)
    for index, message in ipairs(state.store.messages) do if message.id == state.selected_id then return message end end
end

local function chooseImageAttachment(state, context)
    local function attachPath(path)
        path = trim(path)
        local file = io.open(path, "rb")
        if not file then state.status = _("The image could not be opened."); refresh(context); return end
        local data = file:read(MAX_ATTACHMENT_BYTES + 1); file:close()
        local mime = imageMimeForPath(path)
        if not mime then state.status = _("Use a PNG, JPEG, GIF or WEBP image."); refresh(context); return end
        if not data or #data > MAX_ATTACHMENT_BYTES then state.status = _("Images are limited to 512 KB."); refresh(context); return end
        sendDirectMessage(state, context, state.draft_text or "", { mime = mime, data = base64Encode(data) })
    end
    local ok_chooser, FileChooser = pcall(require, "ui/widget/filechooser")
    if ok_chooser and FileChooser then
        local chooser_ui = {
            selected_files = {},
            folder_shortcuts = {
                getShortcutFullName = function() return nil end,
                hasShortcut = function() return false end,
                hasFolderShortcut = function() return false end,
            },
        }
        local ok_new, chooser = pcall(function()
            return FileChooser:new{ name = "dchat_attachment", ui = chooser_ui, path = Device.home_dir or "/", show_path = true, file_filter = function(filename)
                return imageMimeForPath(filename) ~= nil
            end }
        end)
        if ok_new and chooser then
            function chooser:onFileSelect(item)
                local path = item and item.path
                UIManager:close(self)
                UIManager:nextTick(function()
                    if path then attachPath(path) else state.status = _("The image could not be opened."); refresh(context) end
                end)
                return true
            end
            UIManager:show(chooser)
            return
        end
    end
    local dialog
    dialog = InputDialog:new{
        title = _("Attach image"), input = Device.home_dir and (Device.home_dir .. "/") or "/", input_hint = _("Full path to PNG, JPEG, GIF or WEBP (max. 512 KB)"),
        buttons = { { { text = _("Cancel"), callback = function() UIManager:close(dialog) end }, { text = _("Attach"), is_enter_default = true, callback = function()
            local path = dialog:getInputText()
            UIManager:close(dialog)
            attachPath(path)
        end } } },
    }
    showInputDialog(dialog)
end

local function selectedDirectMessage(state)
    for _, message in ipairs(state.store.dm_messages or {}) do if message.id == state.selected_dm_id then return message end end
end

local function reportMessage(state, context, category, note)
    local message = selectedMessage(state)
    if not message then state.status = _("That cached message is no longer available."); state.view = "timeline"; refresh(context); return end
    local clean_note = trim(note or "")
    if clean_note ~= "" then clean_note = safeText(clean_note, MAX_NOTE_BYTES); if not clean_note or #clean_note > 280 then state.status = _("A report note must be plain text with at most 280 characters."); refresh(context); return end end
    local response, code, err = httpJson(state.store, "POST", "/reports", { messageId = message.id, category = category, note = clean_note == "" and nil or clean_note }, true)
    state.status = response and _("Report sent to AppDock moderation.") or (err or _("The report could not be sent."))
    refresh(context)
end

local function promptReport(state, context)
    if not hasIdentity(state.store) then state.status = _("Create a local identity before reporting."); refresh(context); return end
    local dialog
    dialog = InputDialog:new{
        title = _("Report public message"), input = "", input_hint = _("Optional note for moderation"),
        buttons = { { { text = _("Cancel"), callback = function() UIManager:close(dialog) end }, { text = _("Spam"), callback = function() local note = dialog:getInputText(); UIManager:close(dialog); reportMessage(state, context, "spam", note) end }, { text = _("Abuse"), is_enter_default = true, callback = function() local note = dialog:getInputText(); UIManager:close(dialog); reportMessage(state, context, "abuse", note) end } } },
    }
    showInputDialog(dialog)
end

local function removeRecipientLocally(state, context, device_id)
    device_id = trim(tostring(device_id or ""))
    if not device_id:match("^dch_[%w_%-]+$") then return end
    local recipients = {}
    for _, recipient in ipairs(state.store.recipients or {}) do
        if recipient.deviceId ~= device_id then recipients[#recipients + 1] = recipient end
    end
    state.store.recipients = recipients
    local hidden = hiddenRecipientSet(state.store)
    if not hidden[device_id] then
        state.store.hidden_recipient_ids = state.store.hidden_recipient_ids or {}
        state.store.hidden_recipient_ids[#state.store.hidden_recipient_ids + 1] = device_id
    end
    if state.store.selected_recipient_id == device_id then
        clearAttachmentFiles(state)
        state.store.selected_recipient_id, state.store.selected_recipient_name = "", ""
        state.store.dm_messages = {}
        state.selected_dm_id, state.dm_scroll, state.compact_sidebar = nil, 0, true
        state.view = "dm"
    end
    state.recipient_scroll = math.max(0, math.min(state.recipient_scroll or 0, math.max(0, #recipients - 1)))
    saveStore(state.store)
    state.status = _("Contact removed from this reader. It was not deleted from the service.")
    refresh(context)
end

local function confirmRemoveRecipient(state, context, recipient)
    if not recipient then return end
    UIManager:show(ConfirmBox:new{
        text = string.format(_("Remove %s from this reader's chat list? This keeps the other reader and any server-stored chat intact."), recipient.displayName),
        ok_text = _("Remove contact"),
        ok_callback = function() removeRecipientLocally(state, context, recipient.deviceId) end,
    })
end

local function restoreRemovedRecipients(state, context)
    state.store.hidden_recipient_ids = {}
    saveStore(state.store)
    state.status = _("Removed contacts can appear in the next recipient refresh.")
    if hasIdentity(state.store) then
        fetchRecipients(state, context, "")
    else
        refresh(context)
    end
end

local SwipeSurface = InputContainer:extend{ width = nil, height = nil, content = nil, on_swipe = nil }

function SwipeSurface:init()
    self.dimen = Geom:new{ w = self.width, h = self.height }
    self[1] = self.content or emptySizedWidget(self.width, self.height)
    self.ges_events = { SwipeDChatScroll = { GestureRange:new{ ges = "swipe", range = self.dimen } } }
end

function SwipeSurface:paintTo(bb, x, y)
    local range = self.ges_events.SwipeDChatScroll[1].range
    range.x, range.y, range.w, range.h = x, y, self.dimen.w, self.dimen.h
    return InputContainer.paintTo(self, bb, x, y)
end

function SwipeSurface:onSwipeDChatScroll(_, gesture)
    if self.on_swipe then return self.on_swipe(gesture and gesture.direction) == true end
    return false
end

local function clamp(value, minimum, maximum)
    value = tonumber(value) or minimum
    return math.max(minimum, math.min(maximum, value))
end

local function visibleRecentRange(items, offset, capacity)
    local total = #(items or {})
    local maximum = math.max(0, total - capacity)
    offset = clamp(offset, 0, maximum)
    local last = total - offset
    local first = math.max(1, last - capacity + 1)
    return first, last, offset, maximum
end

local function visibleTopRange(items, offset, capacity)
    local total = #(items or {})
    local maximum = math.max(0, total - capacity)
    offset = clamp(offset, 0, maximum)
    return offset + 1, math.min(total, offset + capacity), offset, maximum
end

local function scrollCollection(state, key, total, capacity, direction, context)
    local maximum = math.max(0, total - capacity)
    local current = clamp(state[key], 0, maximum)
    -- A flick should move a useful portion of the visible history while
    -- retaining overlap, rather than nudging the list by a single message.
    local step = math.max(1, math.floor(capacity / 2))
    if current ~= state[key] then state[key] = current end
    if direction == "north" then
        current = math.min(maximum, current + step)
    elseif direction == "south" then
        current = math.max(0, current - step)
    else
        return false
    end
    if current == state[key] then return false end
    state[key] = current
    refresh(context)
    return true
end

local function buildScrollbar(total, offset, capacity, track_height, x, y, palette, px)
    if total <= capacity or track_height <= 0 then return nil end
    local track_width = math.max(px(3), 2)
    local thumb_height = math.max(px(22), math.floor(track_height * capacity / math.max(total, 1)))
    thumb_height = math.min(track_height, thumb_height)
    local maximum = math.max(1, total - capacity)
    local thumb_y = math.floor((track_height - thumb_height) * clamp(offset, 0, maximum) / maximum)
    return OverlapGroup:new{
        dimen = Geom:new{ w = track_width, h = track_height },
        allow_mirroring = false,
        FrameContainer:new{ width = track_width, height = track_height, padding = 0, bordersize = 0, radius = math.floor(track_width / 2), background = palette.surface_variant or palette.surface, emptySizedWidget(track_width, track_height) },
        FrameContainer:new{ width = track_width, height = thumb_height, padding = 0, bordersize = 0, radius = math.floor(track_width / 2), background = palette.primary, emptySizedWidget(track_width, thumb_height), overlap_offset = { 0, thumb_y } },
    }, { x, y }
end

local function dmPreview(text, maximum)
    text = tostring(text or "")
    if #text <= maximum then return text end
    return text:sub(1, math.max(1, maximum - 3)) .. "..."
end

local function attachmentFilePath(state, message)
    if not message or message.attachmentData == "" then return nil end
    state.attachment_files = state.attachment_files or {}
    local cached = state.attachment_files[message.id]
    if cached then
        local file = io.open(cached, "rb")
        if file then file:close(); return cached end
        state.attachment_files[message.id] = nil
    end
    local data = base64Decode(message.attachmentData)
    if not data or #data == 0 or #data > MAX_ATTACHMENT_BYTES then return nil end
    local extension = ({ ["image/png"] = ".png", ["image/jpeg"] = ".jpg", ["image/gif"] = ".gif", ["image/webp"] = ".webp" })[message.attachmentMime]
    if not extension or not ensureAttachmentCacheDir() then return nil end
    local recipient_id = tostring(state.store and state.store.selected_recipient_id or ""):match("^dch_[%w_%-]+$") or "unknown"
    local message_id = tostring(message.id or "")
    if not message_id:match("^%d+$") then return nil end
    local path = ATTACHMENT_CACHE_DIR .. "/dchat_" .. recipient_id .. "_" .. message_id .. extension
    local file = io.open(path, "wb")
    if not file then return nil end
    local write_ok, write_result = pcall(file.write, file, data)
    local close_ok, close_result = pcall(file.close, file)
    if not write_ok or not write_result or not close_ok or not close_result then pcall(os.remove, path); return nil end
    state.attachment_files[message.id] = path
    return path
end

local function directMessageBody(message)
    local body = message.body or ""
    if message.attachmentData ~= "" then
        local notice = _("Image attached")
        body = body ~= "" and body .. "\n" .. notice or notice
    end
    return body
end

local function directBubbleText(message, own)
    local body = directMessageBody(message)
    if own then body = body .. "\n" .. (message.readAt ~= "" and "✓✓" or "✓") end
    return body
end

-- Replies stay plain text on the wire; the blank line introduced by the reply
-- action lets us render the quoted part as its own visual card.
local function splitReplyText(body)
    body = tostring(body or "")
    local separator = body:find(REPLY_SEPARATOR, 1, true)
    if not separator then return nil, body end
    local quote = trim(body:sub(1, separator - 1))
    if not quote:match("^↪ ") then return nil, body end
    return quote, trim(body:sub(separator + #REPLY_SEPARATOR))
end

local function measuredTextHeight(widget, fallback)
    if widget then
        local ok, height = pcall(function() return widget:getTextHeight() end)
        if ok and tonumber(height) and height > 0 then return height end
        ok, height = pcall(function() return widget:getSize().h end)
        if ok and tonumber(height) and height > 0 then return height end
    end
    return math.max(1, tonumber(fallback) or 1)
end

local function releaseTextWidget(widget)
    if widget and type(widget.free) == "function" then pcall(widget.free, widget) end
end

-- ======================================================================
-- DChat 2.2 interface: WhatsApp-style chat list, bubbles, composer and
-- colour emoji. Helpers live in the UI table so the file stays below
-- LuaJIT's limits for file-level locals and per-function upvalues.
-- ======================================================================
local active_px
local UI = { paths = {} }
UI.dir = DataStorage:getDataDir() .. "/appdock_dchat_assets"

function UI.optional(name)
    local ok, module = pcall(require, name)
    if ok and module then return module end
    return nil
end
UI.LeftContainer = UI.optional("ui/widget/container/leftcontainer")
UI.HorizontalGroup = UI.optional("ui/widget/horizontalgroup")
UI.ButtonDialog = UI.optional("ui/widget/buttondialog")

-- ---- bundled image assets (colour emoji + icons) ---------------------
-- Files are written once to <koreader data>/appdock_dchat_assets and then
-- shown with ImageWidget. If anything fails the caller falls back to text.
function UI.assetPath(kind, name)
    local source = ASSETS[kind] and ASSETS[kind][name]
    if not source then return nil end
    local id = (kind == "emoji" and "e1_" or "i1_") .. name
    local cached = UI.paths[id]
    if cached then return cached end
    pcall(function()
        if not lfs.attributes(UI.dir) then lfs.mkdir(UI.dir) end
    end)
    local path = UI.dir .. "/" .. id .. ".png"
    local existing = io.open(path, "rb")
    if existing then
        local size = existing:seek("end")
        existing:close()
        if size and size > 0 then UI.paths[id] = path; return path end
    end
    local data = base64Decode(source)
    if not data or #data == 0 then return nil end
    local temporary = path .. ".tmp"
    local file = io.open(temporary, "wb")
    if not file then return nil end
    local write_ok, wrote = pcall(file.write, file, data)
    local close_ok, closed = pcall(file.close, file)
    if not write_ok or not wrote or not close_ok or not closed then pcall(os.remove, temporary); return nil end
    if not os.rename(temporary, path) then pcall(os.remove, temporary); return nil end
    UI.paths[id] = path
    return path
end

function UI.image(kind, name, size)
    size = math.max(1, math.floor(size or 1))
    local path = UI.assetPath(kind, name)
    if not path then return nil end
    local loaded, ImageWidget = pcall(require, "ui/widget/imagewidget")
    if not loaded or not ImageWidget then return nil end
    local ok, widget = pcall(function()
        return ImageWidget:new{ file = path, width = size, height = size, scale_factor = 0, alpha = true, file_do_cache = true }
    end)
    return ok and widget or nil
end

-- ---- UTF-8 / emoji helpers ------------------------------------------
function UI.codepoints(text)
    local result, index, total = {}, 1, #text
    while index <= total do
        local lead = text:byte(index)
        local code, length
        if lead < 0x80 then code, length = lead, 1
        elseif lead >= 0xC2 and lead <= 0xDF then code, length = lead - 0xC0, 2
        elseif lead >= 0xE0 and lead <= 0xEF then code, length = lead - 0xE0, 3
        elseif lead >= 0xF0 and lead <= 0xF4 then code, length = lead - 0xF0, 4
        else return nil end
        for offset = 1, length - 1 do
            local follow = text:byte(index + offset)
            if not follow or follow < 0x80 or follow > 0xBF then return nil end
            code = code * 64 + (follow - 0x80)
        end
        result[#result + 1] = code
        index = index + length
    end
    return result
end

function UI.utf8char(code)
    if code < 0x80 then return string.char(code) end
    if code < 0x800 then return string.char(0xC0 + math.floor(code / 64), 0x80 + code % 64) end
    if code < 0x10000 then
        return string.char(0xE0 + math.floor(code / 4096), 0x80 + math.floor(code / 64) % 64, 0x80 + code % 64)
    end
    return string.char(0xF0 + math.floor(code / 262144), 0x80 + math.floor(code / 4096) % 64, 0x80 + math.floor(code / 64) % 64, 0x80 + code % 64)
end

function UI.emojiText(key)
    local text = UI.utf8char(tonumber(key, 16) or 63)
    if ASSETS.vs16[key] then text = text .. "\239\184\143" end
    return text
end

function UI.isSkinTone(code)
    return code >= 0x1F3FB and code <= 0x1F3FF
end

function UI.isEmojiBase(code)
    return (code >= 0x1F300 and code <= 0x1FAFF) or (code >= 0x2600 and code <= 0x27BF)
        or code == 0x2B50 or code == 0x2B55 or code == 0x2B1B or code == 0x2B1C
        or (code >= 0x23E9 and code <= 0x23FA) or code == 0x231A or code == 0x231B
        or code == 0xA9 or code == 0xAE or code == 0x203C or code == 0x2049 or code == 0x2122 or code == 0x2139
end

-- Returns the list of emoji keys when `text` consists only of emoji (and
-- spaces), at most `maximum` of them; otherwise nil. Variation selectors and
-- skin tones are dropped so "👍🏽" falls back to the plain 👍 image.
function UI.emojiKeys(text, maximum)
    local codes = UI.codepoints(tostring(text or ""))
    if not codes or #codes == 0 then return nil end
    local keys, index, total = {}, 1, #codes
    while index <= total do
        local code = codes[index]
        if code == 0x20 or code == 0xA0 or code == 0x2063 then
            index = index + 1
        elseif UI.isEmojiBase(code) and not UI.isSkinTone(code) then
            local parts = { code }
            index = index + 1
            while index <= total do
                local following = codes[index]
                if following == 0xFE0F or following == 0x20E3 or UI.isSkinTone(following) or (following >= 0xE0020 and following <= 0xE007F) then
                    index = index + 1
                elseif following == 0x200D and codes[index + 1] and UI.isEmojiBase(codes[index + 1]) then
                    parts[#parts + 1] = codes[index + 1]
                    index = index + 2
                else
                    break
                end
            end
            local hex = {}
            for part_index = 1, #parts do hex[part_index] = string.format("%x", parts[part_index]) end
            keys[#keys + 1] = table.concat(hex, "-")
            if #keys > maximum then return nil end
        else
            return nil
        end
    end
    if #keys == 0 then return nil end
    return keys
end

function UI.emojiSupported(keys)
    for index = 1, #keys do
        if not ASSETS.emoji[keys[index]] then return false end
    end
    return true
end

function UI.jumboSize(count, px)
    if count <= 1 then return px(54) end
    if count == 2 then return px(46) end
    if count == 3 then return px(40) end
    if count <= 5 then return px(32) end
    return px(26)
end

function UI.preview(text, maximum)
    text = tostring(text or "")
    if #text <= maximum then return text end
    local cut = math.max(1, maximum - 3)
    while cut > 1 do
        local byte = text:byte(cut + 1)
        if byte and byte >= 0x80 and byte < 0xC0 then cut = cut - 1 else break end
    end
    return text:sub(1, cut) .. "..."
end

function UI.initial(name)
    local first = tostring(name or ""):match("^[\1-\127\194-\244][\128-\191]*") or "?"
    return first:upper()
end

UI.avatar_hex = { "#00A884", "#7F66FF", "#E5566B", "#2F8FCB", "#D9822B", "#8B6B4E", "#2BAE66", "#B14EC0" }
UI.avatar_colors = {}
function UI.nameColor(name)
    name = tostring(name or "")
    local hash = 0
    for index = 1, #name do hash = (hash * 31 + name:byte(index)) % 997 end
    local slot = hash % #UI.avatar_hex + 1
    local color = UI.avatar_colors[slot]
    if not color then
        color = WA.color(UI.avatar_hex[slot], WA.header)
        UI.avatar_colors[slot] = color
    end
    return color
end

-- ---- time helpers ----------------------------------------------------
function UI.daysFromCivil(year, month, day)
    if month <= 2 then year = year - 1 end
    local era = math.floor(year / 400)
    local year_of_era = year - era * 400
    local shifted = (month + 9) % 12
    local day_of_year = math.floor((153 * shifted + 2) / 5) + day - 1
    local day_of_era = year_of_era * 365 + math.floor(year_of_era / 4) - math.floor(year_of_era / 100) + day_of_year
    return era * 146097 + day_of_era - 719468
end

-- Parses "2026-10-24T08:15:30Z" style stamps. Stamps with an explicit zone
-- (Z, +00:00, +02:00 ...) are converted to the reader's local time; stamps
-- without a zone are assumed to be local already.
function UI.parseTime(value)
    value = tostring(value or "")
    local year, month, day, hour, minute = value:match("(%d%d%d%d)%-(%d%d)%-(%d%d)[T ](%d%d):(%d%d)")
    if not year then return nil end
    year, month, day, hour, minute = tonumber(year), tonumber(month), tonumber(day), tonumber(hour), tonumber(minute)
    local utc = value:find("Z%s*$") ~= nil
    local sign, offset_hours, offset_minutes = value:match("([%+%-])(%d%d):?(%d%d)%s*$")
    if utc or sign then
        local epoch = UI.daysFromCivil(year, month, day) * 86400 + hour * 3600 + minute * 60
        if sign then
            local shift = tonumber(offset_hours) * 3600 + tonumber(offset_minutes) * 60
            epoch = epoch + (sign == "+" and -shift or shift)
        end
        local ok, local_time = pcall(os.date, "*t", epoch)
        if ok and type(local_time) == "table" then
            year, month, day, hour, minute = local_time.year, local_time.month, local_time.day, local_time.hour, local_time.min
        end
    end
    return {
        year = year, month = month, day = day, hour = hour, min = minute,
        key = string.format("%04d-%02d-%02d", year, month, day),
        clock = string.format("%02d:%02d", hour, minute),
    }
end

function UI.dayLabel(stamp)
    local today = os.date("%Y-%m-%d")
    local yesterday = os.date("%Y-%m-%d", os.time() - 86400)
    if stamp.key == today then return _("Today") end
    if stamp.key == yesterday then return _("Yesterday") end
    return string.format("%02d.%02d.%04d", stamp.day, stamp.month, stamp.year)
end

-- ---- basic widgets ---------------------------------------------------
local ActionButton = InputContainer:extend{
    width = nil,
    height = nil,
    title = "",
    body = nil,
    primary = false,
    button_background = nil,
    button_foreground = nil,
    callback = nil,
    hold_callback = nil,
    icon = nil,
    emoji = nil,
    icon_size = nil,
    radius = nil,
    transparent = false,
    align = nil,
    font_size = nil,
    bold = false,
}

function ActionButton:init()
    self.dimen = Geom:new{ w = self.width, h = self.height }
    local px = active_px or scale
    local palette = active_palette or paletteFor()
    local foreground = self.button_foreground or (self.primary and palette.on_primary or palette.on_surface)
    local background = self.button_background or (self.primary and palette.primary or palette.surface)
    local icon_widget
    local icon_size = self.icon_size or math.floor(math.min(self.width, self.height) * .5)
    if self.icon then icon_widget = UI.image("icon", self.icon, icon_size) end
    if self.emoji then icon_widget = UI.image("emoji", self.emoji, icon_size) end
    local content
    if icon_widget then
        content = CenterContainer:new{ dimen = self.dimen, icon_widget }
    elseif self.body then
        content = TextBoxWidget:new{
            bgcolor = background,
            text = self.body,
            face = Font:getFace("smallinfofont", self.font_size or math.max(px(8), math.floor(self.height * .18))),
            width = math.max(1, self.width - px(12)),
            height = math.max(1, self.height - px(12)),
            line_height = 0.30,
            alignment = "left",
            fgcolor = foreground,
        }
    else
        local label = TextWidget:new{
            text = self.title,
            face = Font:getFace("smallinfofont", self.font_size or math.max(px(8), math.floor(self.height * .22))),
            fgcolor = foreground,
            bold = self.primary or self.bold,
            max_width = math.max(1, self.width - px(8)),
        }
        if self.align == "left" and UI.LeftContainer and UI.HorizontalGroup then
            content = UI.LeftContainer:new{
                dimen = self.dimen,
                UI.HorizontalGroup:new{ HorizontalSpan:new{ width = px(6) }, label },
            }
        else
            content = CenterContainer:new{ dimen = self.dimen, label }
        end
    end
    local options = {
        width = self.width,
        height = self.height,
        padding = (self.body and not icon_widget) and px(6) or 0,
        bordersize = 0,
        radius = self.radius or math.max(2, math.floor(self.height * .22)),
        content,
    }
    if not self.transparent then options.background = self.button_background or background end
    self[1] = FrameContainer:new(options)
    self.ges_events = { TapDChatAction = { GestureRange:new{ ges = "tap", range = self.dimen } } }
    if self.hold_callback then
        self.ges_events.HoldDChatAction = { GestureRange:new{ ges = "hold", range = self.dimen } }
    end
end

function ActionButton:paintTo(bb, x, y)
    local range = self.ges_events.TapDChatAction[1].range
    range.x, range.y, range.w, range.h = x, y, self.dimen.w, self.dimen.h
    return InputContainer.paintTo(self, bb, x, y)
end

function ActionButton:onTapDChatAction()
    if self.callback then self.callback() end
    return true
end

function ActionButton:onHoldDChatAction()
    if self.hold_callback then self.hold_callback() end
    return true
end

-- A tappable rounded frame around arbitrary content (chat bubbles, list rows).
local ChatBubble = InputContainer:extend{
    width = nil,
    height = nil,
    content = nil,
    background = nil,
    radius = 0,
    callback = nil,
    hold_callback = nil,
}

function ChatBubble:init()
    self.dimen = Geom:new{ w = self.width, h = self.height }
    local options = {
        width = self.width,
        height = self.height,
        padding = 0,
        bordersize = 0,
        radius = self.radius or 0,
        self.content or emptySizedWidget(self.width, self.height),
    }
    if self.background then options.background = self.background end
    self[1] = FrameContainer:new(options)
    self.ges_events = { TapDChatBubble = { GestureRange:new{ ges = "tap", range = self.dimen } } }
    if self.hold_callback then
        self.ges_events.HoldDChatBubble = { GestureRange:new{ ges = "hold", range = self.dimen } }
    end
end

function ChatBubble:paintTo(bb, x, y)
    local range = self.ges_events.TapDChatBubble[1].range
    range.x, range.y, range.w, range.h = x, y, self.dimen.w, self.dimen.h
    return InputContainer.paintTo(self, bb, x, y)
end

function ChatBubble:onTapDChatBubble()
    if self.callback then self.callback() end
    return true
end

function ChatBubble:onHoldDChatBubble()
    if self.hold_callback then self.hold_callback() end
    return true
end

local function makeBubbleText(text, width, font_size, foreground, background)
    if text == nil or text == "" then return nil end
    return TextBoxWidget:new{
        text = text,
        face = Font:getFace("smallinfofont", font_size),
        width = math.max(1, width),
        line_height = 0.22,
        alignment = "left",
        fgcolor = foreground,
        -- Transparent glyphs on new hosts; match the exact surface on old ones.
        bgcolor = background,
    }
end

-- ---- bubbles ----------------------------------------------------------
function UI.textWidth(text, face)
    local ok, width = pcall(function()
        local widget = TextWidget:new{ text = text, face = face }
        local measured = widget:getSize().w
        if widget.free then widget:free() end
        return measured
    end)
    if ok and tonumber(width) then return width end
    return #text * scale(7)
end

function UI.placeMeta(parts, x, y, gap, elements)
    local cursor = x
    for index = 1, #parts do
        local widget = parts[index]
        widget.overlap_offset = { cursor, y }
        elements[#elements + 1] = widget
        cursor = cursor + widget:getSize().w + gap
    end
end

-- Lays out author / image / quote / text / time inside one bubble at a
-- given font size. Returns width, height and the positioned elements.
function UI.layoutText(a, c)
    local px = a.px
    local face = Font:getFace("smallinfofont", c.font_size)
    local elements = {}
    local body = a.body or ""
    local body_width, single = 0, true
    if body ~= "" then
        local natural = (#body > 200) and (c.inner_max + 1) or UI.textWidth(body, face)
        if natural <= c.inner_max then
            body_width = natural + px(3)
        else
            body_width, single = c.inner_max, false
        end
    end
    local author_widget, author_size
    if a.author and a.author ~= "" then
        author_widget = TextWidget:new{
            text = a.author,
            face = Font:getFace("smallinfofont", math.max(px(7), c.font_size - px(1))),
            fgcolor = UI.nameColor(a.author),
            bold = true,
            max_width = c.inner_max,
        }
        author_size = author_widget:getSize()
    end
    local content_width = math.max(body_width, author_size and author_size.w or 0, c.meta_width)
    local image_width, image_height = 0, 0
    if a.image_widget then
        local size = a.image_widget:getSize()
        image_width, image_height = size.w, size.h
        content_width = math.max(content_width, image_width)
    end
    local quote_face_size = math.max(px(6), math.floor(c.font_size * .88))
    local quote_inset, quote_bar = px(4), px(3)
    if a.quote_text then
        local quote_natural = UI.textWidth(UI.preview(a.quote_text, 160), Font:getFace("smallinfofont", quote_face_size))
        content_width = math.max(content_width, math.min(c.inner_max, quote_natural + 2 * quote_inset + quote_bar + px(6)))
    end
    local inline_meta = false
    if body ~= "" and single and c.meta_width > 0 and body_width + px(8) + c.meta_width <= c.inner_max then
        inline_meta = true
        content_width = math.max(content_width, body_width + px(8) + c.meta_width)
    end
    content_width = math.min(content_width, c.inner_max)

    local y = c.pad_y
    if author_widget then
        author_widget.overlap_offset = { c.pad_x, y }
        elements[#elements + 1] = author_widget
        y = y + author_size.h + px(1)
    end
    if a.image_widget then
        a.image_widget.overlap_offset = { c.pad_x + math.floor((content_width - image_width) / 2), y }
        elements[#elements + 1] = a.image_widget
        y = y + image_height + c.gap
    end
    if a.quote_text then
        local inner_width = content_width - 2 * quote_inset
        local quote_widget = makeBubbleText(UI.preview(a.quote_text, 160), inner_width - quote_bar - quote_inset, quote_face_size, WA.sub, c.own and WA.quote_own or WA.quote_other)
        local quote_height = measuredTextHeight(quote_widget, quote_face_size * 1.3)
        local card_height = quote_height + 2 * quote_inset
        quote_widget.overlap_offset = { quote_bar + quote_inset, 0 }
        local bar = FrameContainer:new{ width = quote_bar, height = quote_height, padding = 0, bordersize = 0, background = WA.send, emptySizedWidget(quote_bar, quote_height) }
        bar.overlap_offset = { 0, 0 }
        local card = FrameContainer:new{
            width = content_width,
            height = card_height,
            padding = quote_inset,
            bordersize = 0,
            radius = px(4),
            background = c.own and WA.quote_own or WA.quote_other,
            OverlapGroup:new{ dimen = Geom:new{ w = inner_width, h = quote_height }, allow_mirroring = false, bar, quote_widget },
        }
        card.overlap_offset = { c.pad_x, y }
        elements[#elements + 1] = card
        y = y + card_height + c.gap
    end
    if body ~= "" then
        local body_widget = makeBubbleText(body, content_width, c.font_size, WA.text, c.background)
        local body_height = measuredTextHeight(body_widget, c.font_size * 1.3)
        body_widget.overlap_offset = { c.pad_x, y }
        elements[#elements + 1] = body_widget
        if inline_meta then
            UI.placeMeta(c.meta_parts, c.pad_x + content_width - c.meta_width, y + body_height - c.meta_height, px(3), elements)
        end
        y = y + body_height
    end
    if c.meta_width > 0 and not inline_meta then
        UI.placeMeta(c.meta_parts, c.pad_x + content_width - c.meta_width, y + px(1), px(3), elements)
        y = y + c.meta_height + px(1)
    end
    return { width = content_width + 2 * c.pad_x, height = y + c.pad_y, elements = elements }
end

-- Emoji-only messages: big colour emoji without a bubble, like WhatsApp.
function UI.jumboBubble(a, images, size, c)
    local px = a.px
    local pad_x, pad_y = px(6), px(3)
    local elements = {}
    local row_width = #images * size + (#images - 1) * px(4)
    local author_widget, author_size
    if a.author and a.author ~= "" then
        author_widget = TextWidget:new{
            text = a.author,
            face = Font:getFace("smallinfofont", px(9)),
            fgcolor = UI.nameColor(a.author),
            bold = true,
            max_width = math.max(px(60), c.inner_max),
        }
        author_size = author_widget:getSize()
    end
    local content_width = math.max(row_width, c.meta_width, author_size and author_size.w or 0)
    local y = pad_y
    if author_widget then
        author_widget.overlap_offset = { pad_x, y }
        elements[#elements + 1] = author_widget
        y = y + author_size.h + px(1)
    end
    local x = pad_x + (a.own and (content_width - row_width) or 0)
    for index = 1, #images do
        images[index].overlap_offset = { x, y }
        elements[#elements + 1] = images[index]
        x = x + size + px(4)
    end
    y = y + size + px(2)
    if c.meta_width > 0 then
        UI.placeMeta(c.meta_parts, pad_x + content_width - c.meta_width, y, px(3), elements)
        y = y + c.meta_height
    end
    local width, height = content_width + 2 * pad_x, y + pad_y
    return ChatBubble:new{
        width = width,
        height = height,
        content = OverlapGroup:new{ dimen = Geom:new{ w = width, h = height }, allow_mirroring = false, unpack(elements) },
        callback = a.callback,
        hold_callback = a.hold_callback,
    }
end

function UI.buildBubble(a)
    local px = a.px
    local own = a.own == true
    local c = {
        own = own,
        pad_x = px(8), pad_y = px(5), gap = px(3),
        background = own and WA.own or WA.other,
        meta_parts = {}, meta_width = 0, meta_height = 0,
    }
    local max_bubble = math.max(px(130), math.floor(a.avail_width * .82))
    c.inner_max = max_bubble - 2 * c.pad_x
    local meta_face = Font:getFace("smallinfofont", px(7))
    if a.time_text and a.time_text ~= "" then
        c.meta_parts[#c.meta_parts + 1] = TextWidget:new{ text = a.time_text, face = meta_face, fgcolor = WA.sub }
    end
    if a.ticks then
        c.meta_parts[#c.meta_parts + 1] = TextWidget:new{ text = a.read and "✓✓" or "✓", face = meta_face, fgcolor = a.read and WA.tick_read or WA.sub }
    end
    for index = 1, #c.meta_parts do
        local size = c.meta_parts[index]:getSize()
        c.meta_width = c.meta_width + size.w + (index > 1 and px(3) or 0)
        c.meta_height = math.max(c.meta_height, size.h)
    end

    local keys = (not a.quote_text and not a.image_widget) and UI.emojiKeys(a.body, 8) or nil
    if keys and UI.emojiSupported(keys) then
        local size = UI.jumboSize(#keys, px)
        local images = {}
        for index = 1, #keys do
            images[index] = UI.image("emoji", keys[index], size)
            if not images[index] then images = nil; break end
        end
        if images then return UI.jumboBubble(a, images, size, c) end
    end

    local font_size = keys and px(22) or px(11)
    local min_font = math.max(5, px(6))
    local layout
    repeat
        c.font_size = font_size
        layout = UI.layoutText(a, c)
        if layout.height <= a.max_height or font_size <= min_font then break end
        for index = 1, #layout.elements do releaseTextWidget(layout.elements[index]) end
        font_size = math.max(min_font, font_size - math.max(1, px(1)))
    until false

    return ChatBubble:new{
        width = layout.width,
        height = layout.height,
        content = OverlapGroup:new{ dimen = Geom:new{ w = layout.width, h = layout.height }, allow_mirroring = false, unpack(layout.elements) },
        background = c.background,
        radius = px(8),
        callback = a.callback,
        hold_callback = a.hold_callback,
    }
end

-- A full-width row: optional centred date pill above the bubble.
function UI.buildRow(a)
    local px = a.px
    local elements = {}
    local pill_height = 0
    if a.date_label then
        local label = TextWidget:new{ text = a.date_label, face = Font:getFace("smallinfofont", px(8)), fgcolor = WA.sub }
        local size = label:getSize()
        local pill_width, height = size.w + 2 * px(10), size.h + 2 * px(3)
        local pill = FrameContainer:new{
            width = pill_width,
            height = height,
            padding = 0,
            bordersize = 0,
            radius = math.floor(height / 2),
            background = WA.pill,
            CenterContainer:new{ dimen = Geom:new{ w = pill_width, h = height }, label },
        }
        pill.overlap_offset = { math.floor((a.width - pill_width) / 2), 0 }
        elements[#elements + 1] = pill
        pill_height = height + px(5)
    end
    local bubble = a.bubble
    bubble.overlap_offset = { a.own and (a.width - a.margin - bubble.width) or a.margin, pill_height }
    elements[#elements + 1] = bubble
    local total = pill_height + bubble.height
    local row = OverlapGroup:new{ dimen = Geom:new{ w = a.width, h = total }, allow_mirroring = false, unpack(elements) }
    row.height, row.width = total, a.width
    return row
end

function UI.visibleRows(items, offset, available_height, gap, make_row)
    local total = #(items or {})
    local normalized = clamp(offset, 0, math.max(0, total - 1))
    local latest = total - normalized
    local selected, used = {}, 0
    for index = latest, 1, -1 do
        local row = make_row(items[index], available_height, index)
        local extra = row.height + (#selected > 0 and gap or 0)
        if #selected > 0 and used + extra > available_height then break end
        selected[#selected + 1] = { index = index, row = row }
        used = used + extra
    end
    local ordered = {}
    for index = #selected, 1, -1 do ordered[#ordered + 1] = selected[index] end
    return ordered, #ordered, used, normalized
end

-- ---- popup menus -----------------------------------------------------
function UI.showMenu(items, title)
    if not UI.ButtonDialog then return false end
    local dialog
    local rows = {}
    for index = 1, #items do
        local item = items[index]
        rows[#rows + 1] = { { text = item.text, callback = function()
            UIManager:close(dialog)
            item.callback()
        end } }
    end
    local ok, created = pcall(function() return UI.ButtonDialog:new{ title = title, title_align = "center", buttons = rows } end)
    if not ok or not created then return false end
    dialog = created
    UIManager:show(dialog)
    return true
end

function UI.copyText(text)
    local ok = pcall(function() Device.input.setClipboardText(text) end)
    UIManager:show(InfoMessage:new{ text = ok and _("Copied") or _("Copy is not available on this device."), timeout = 1 })
end

function UI.messageMenu(state, context, message, mode)
    local public = mode == "public"
    local items = {}
    if not public then
        items[#items + 1] = { text = _("Reply"), callback = function()
            local quote = "↪ " .. message.authorName .. ": " .. UI.preview(message.body ~= "" and message.body or _("Image attached"), 140)
            promptDirectMessage(state, context, quote .. "\n\n" .. REPLY_SEPARATOR .. "\n")
        end }
    end
    if message.body and message.body ~= "" then
        items[#items + 1] = { text = _("Copy text"), callback = function() UI.copyText(message.body) end }
    end
    local details = { text = (not public and message.attachmentData ~= "") and _("Open image / details") or _("Details"), callback = function()
        if public then
            state.selected_id = message.id
            state.view = "message"
        else
            clearAttachmentFiles(state)
            state.selected_dm_id = message.id
            state.view = "dm_message"
        end
        refresh(context)
    end }
    items[#items + 1] = details
    if public then
        items[#items + 1] = { text = _("Report"), callback = function()
            state.selected_id = message.id
            promptReport(state, context)
        end }
    end
    if not UI.showMenu(items, message.authorName) then details.callback() end
end

-- ---- header, chat list, chat panel ------------------------------------
function UI.avatar(diameter, name, color, px)
    local label = TextWidget:new{
        text = UI.initial(name),
        face = Font:getFace("cfont", math.max(px(10), math.floor(diameter * .46))),
        fgcolor = WA.white,
        bold = true,
    }
    return FrameContainer:new{
        width = diameter,
        height = diameter,
        padding = 0,
        bordersize = 0,
        radius = math.floor(diameter / 2),
        background = color,
        CenterContainer:new{ dimen = Geom:new{ w = diameter, h = diameter }, label },
    }
end

function UI.header(elements, context, width, o)
    local px = context.px or scale
    local h, margin = o.height, o.margin
    elements[#elements + 1] = FrameContainer:new{ width = width, height = h, padding = 0, bordersize = 0, background = WA.header, emptySizedWidget(width, h) }
    local x = margin
    if o.back then
        local back_width = math.floor(h * .8)
        elements[#elements + 1] = ActionButton:new{ width = back_width, height = h, icon = "back", icon_size = math.floor(h * .42), transparent = true, radius = 0, callback = o.back, overlap_offset = { 0, 0 } }
        x = back_width
    end
    local action_width = math.floor(h * .78)
    local right = width
    for index = #o.actions, 1, -1 do
        local action = o.actions[index]
        right = right - action_width
        elements[#elements + 1] = ActionButton:new{ width = action_width, height = h, icon = action.icon, icon_size = math.floor(h * .44), transparent = true, radius = 0, callback = action.callback, overlap_offset = { right, 0 } }
    end
    if o.avatar_name then
        local diameter = math.floor(h * .66)
        local avatar = UI.avatar(diameter, o.avatar_name, o.avatar_color, px)
        avatar.overlap_offset = { x, math.floor((h - diameter) / 2) }
        elements[#elements + 1] = avatar
        x = x + diameter + math.floor(margin * .8)
    end
    local text_width = math.max(px(20), right - x - math.floor(margin * .5))
    elements[#elements + 1] = TextWidget:new{ text = o.title, face = Font:getFace("cfont", math.max(px(13), math.floor(h * .34))), fgcolor = WA.white, bold = true, max_width = text_width, overlap_offset = { x, math.floor(h * .10) } }
    if o.subtitle and o.subtitle ~= "" then
        elements[#elements + 1] = TextWidget:new{ text = o.subtitle, face = Font:getFace("smallinfofont", math.max(px(7), math.floor(h * .19))), fgcolor = WA.header_sub, max_width = text_width, overlap_offset = { x, math.floor(h * .58) } }
    end
end

function UI.goSettings(state, context)
    state.view = "settings"
    refresh(context)
end

function UI.sidebarMenu(state, context)
    local items = {
        { text = _("Settings"), callback = function() UI.goSettings(state, context) end },
        { text = _("Restore removed contacts"), callback = function() restoreRemovedRecipients(state, context) end },
    }
    if not UI.showMenu(items, "DChat") then UI.goSettings(state, context) end
end

function UI.chatRow(o)
    local px, width, height, margin = o.px, o.width, o.height, o.margin
    local diameter = math.floor(height * .68)
    local text_x = margin + diameter + math.floor(margin * .8)
    local parts = {}
    local avatar = UI.avatar(diameter, o.name, o.color, px)
    avatar.overlap_offset = { margin, math.floor((height - diameter) / 2) }
    parts[#parts + 1] = avatar
    local badge_diameter = math.floor(height * .36)
    local text_width = width - text_x - margin - ((o.unread or 0) > 0 and (badge_diameter + margin) or 0)
    parts[#parts + 1] = TextWidget:new{ text = o.name, face = Font:getFace("cfont", math.max(px(10), math.floor(height * .22))), fgcolor = WA.text, bold = true, max_width = text_width, overlap_offset = { text_x, math.floor(height * .13) } }
    parts[#parts + 1] = TextWidget:new{ text = o.subtitle, face = Font:getFace("smallinfofont", math.max(px(8), math.floor(height * .17))), fgcolor = (o.unread or 0) > 0 and WA.send or WA.sub, max_width = text_width, overlap_offset = { text_x, math.floor(height * .55) } }
    if (o.unread or 0) > 0 then
        local count = TextWidget:new{ text = tostring(o.unread), face = Font:getFace("smallinfofont", math.max(px(7), math.floor(badge_diameter * .46))), fgcolor = WA.white, bold = true }
        local badge = FrameContainer:new{
            width = badge_diameter, height = badge_diameter, padding = 0, bordersize = 0,
            radius = math.floor(badge_diameter / 2), background = WA.badge,
            CenterContainer:new{ dimen = Geom:new{ w = badge_diameter, h = badge_diameter }, count },
        }
        badge.overlap_offset = { width - margin - badge_diameter, math.floor((height - badge_diameter) / 2) }
        parts[#parts + 1] = badge
    end
    local divider = FrameContainer:new{ width = width - text_x, height = 1, padding = 0, bordersize = 0, background = WA.divider, emptySizedWidget(width - text_x, 1) }
    divider.overlap_offset = { text_x, height - 1 }
    parts[#parts + 1] = divider
    return ChatBubble:new{
        width = width,
        height = height,
        content = OverlapGroup:new{ dimen = Geom:new{ w = width, h = height }, allow_mirroring = false, unpack(parts) },
        background = o.selected and WA.selected or WA.white,
        callback = o.callback,
        hold_callback = o.hold_callback,
    }
end

function UI.buildSidebar(state, context, width, height, highlight)
    local px = context.px or scale
    local margin = math.max(px(8), math.floor(width / 40))
    local header_height = math.max(px(46), math.floor(height * .09))
    local status_height = math.max(px(16), math.floor(height * .035))
    local row_height = math.max(px(56), math.floor(height * .105))
    local list_end = height - status_height
    local capacity = math.max(1, math.floor(math.max(0, list_end - header_height) / row_height))
    local entries = { { lounge = true } }
    for _, recipient in ipairs(state.store.recipients or {}) do entries[#entries + 1] = recipient end
    local first, last, normalized = visibleTopRange(entries, state.recipient_scroll or 0, capacity)
    state.recipient_scroll = normalized
    local elements = {
        FrameContainer:new{ width = width, height = height, padding = 0, bordersize = 0, background = WA.white, emptySizedWidget(width, height) },
    }
    UI.header(elements, context, width, {
        height = header_height, margin = margin, title = "DChat",
        subtitle = hasIdentity(state.store) and state.store.display_name or _("No local identity"),
        actions = {
            { icon = "search", callback = function() promptRecipientSearch(state, context) end },
            { icon = "refresh", callback = function() fetchRecipients(state, context, "") end },
            { icon = "more", callback = function() UI.sidebarMenu(state, context) end },
        },
    })
    local lounge_selected = highlight and (state.view == "timeline" or not selectedRecipient(state))
    local y = header_height
    for index = first, last do
        local entry = entries[index]
        local row
        if entry.lounge then
            local newest = (state.store.messages or {})[#(state.store.messages or {})]
            row = UI.chatRow{
                px = px, width = width, height = row_height, margin = margin,
                name = _("AppDock Lounge"), color = WA.send, selected = lounge_selected,
                subtitle = newest and UI.preview(newest.authorName .. ": " .. newest.body, 44) or _("Public room"),
                callback = function() state.compact_sidebar = false; state.view = "timeline"; refresh(context) end,
            }
        else
            local unread = tonumber(entry.unreadCount) or 0
            local is_selected = highlight and state.view ~= "timeline" and entry.deviceId == state.store.selected_recipient_id
            local subtitle = unread > 0 and string.format(_("%d new messages"), unread) or _("Private chat")
            row = UI.chatRow{
                px = px, width = width, height = row_height, margin = margin,
                name = entry.displayName, color = UI.nameColor(entry.displayName), selected = is_selected,
                unread = unread, subtitle = subtitle,
                callback = function()
                    clearAttachmentFiles(state)
                    state.store.selected_recipient_id = entry.deviceId
                    state.store.selected_recipient_name = entry.displayName
                    state.compact_sidebar = false
                    state.view = "dm_conversation"
                    state.dm_scroll = 0
                    saveStore(state.store)
                    fetchConversation(state, context)
                end,
                hold_callback = function() confirmRemoveRecipient(state, context, entry) end,
            }
        end
        row.overlap_offset = { 0, y }
        elements[#elements + 1] = row
        y = y + row_height
    end
    if #(state.store.recipients or {}) == 0 then
        elements[#elements + 1] = TextBoxWidget:new{
            bgcolor = WA.white,
            text = _("No contacts yet. Tap the magnifier to find a reader and start a private chat."),
            face = Font:getFace("smallinfofont", math.max(px(8), math.floor(row_height * .17))),
            width = width - 2 * margin, alignment = "center", fgcolor = WA.sub,
            overlap_offset = { margin, header_height + row_height + margin },
        }
    end
    if (state.status or "") ~= "" then
        elements[#elements + 1] = TextWidget:new{ text = state.status, face = Font:getFace("smallinfofont", math.max(px(7), math.floor(status_height * .48))), fgcolor = WA.sub, max_width = width - 2 * margin, overlap_offset = { margin, height - status_height + 2 } }
    end
    return SwipeSurface:new{
        width = width,
        height = height,
        content = OverlapGroup:new{ dimen = Geom:new{ w = width, h = height }, allow_mirroring = false, unpack(elements) },
        on_swipe = function(direction) return scrollCollection(state, "recipient_scroll", #entries, capacity, direction, context) end,
    }
end

function UI.insertEmoji(state, mode, key)
    local text = UI.emojiText(key)
    if mode == "public" then
        local draft = state.public_draft or ""
        if #draft + #text <= 480 then state.public_draft = draft .. text end
    else
        local draft = state.draft_text or ""
        if #draft + #text <= MAX_TEXT_BYTES - 40 then state.draft_text = draft .. text end
    end
end

function UI.messageRow(state, context, message, previous, mode, width, margin, max_height)
    local px = context.px or scale
    local public = mode == "public"
    local own
    if public then
        own = hasIdentity(state.store) and message.authorName == state.store.display_name or false
    else
        own = message.senderDeviceId == state.store.device_id or (message.senderDeviceId == "" and message.authorName == state.store.display_name)
    end
    local stamp = UI.parseTime(message.createdAt)
    local previous_stamp = previous and UI.parseTime(previous.createdAt) or nil
    local date_label = (stamp and (not previous_stamp or previous_stamp.key ~= stamp.key)) and UI.dayLabel(stamp) or nil
    local body, quote_text, image_widget = message.body or "", nil, nil
    if not public then
        quote_text, body = splitReplyText(body)
        local image_path = attachmentFilePath(state, message)
        if image_path then
            local box_width = math.min(px(230), math.floor(width * .6))
            local box_height = math.min(px(170), math.floor(max_height * .45))
            image_widget = safeImageWidget{ file = image_path, width = box_width, height = box_height, scale_factor = 0, file_do_cache = false }
        end
        if message.attachmentData ~= "" and not image_widget then
            body = (body ~= "" and (body .. "\n") or "") .. _("Image attached")
        end
    end
    local bubble = UI.buildBubble{
        px = px, avail_width = width - 2 * margin, max_height = max_height - (date_label and px(26) or 0),
        own = own, author = (public and not own) and message.authorName or nil,
        body = body, quote_text = quote_text, image_widget = image_widget,
        time_text = stamp and stamp.clock or "", ticks = (not public) and own, read = (message.readAt or "") ~= "",
        callback = function() UI.messageMenu(state, context, message, mode) end,
    }
    return UI.buildRow{ px = px, bubble = bubble, own = own, width = width, margin = margin, date_label = date_label }
end

function UI.buildChatPanel(state, context, width, height, compact, mode)
    local palette = active_palette
    local px = context.px or scale
    local public = mode == "public"
    local recipient = (not public) and selectedRecipient(state) or nil
    if not public and not recipient then return UI.buildChatPanel(state, context, width, height, compact, "public") end
    local messages = public and (state.store.messages or {}) or (state.store.dm_messages or {})
    local scroll_key = public and "public_scroll" or "dm_scroll"
    local margin, gap = math.max(px(8), math.floor(width / 60)), math.max(px(4), math.floor(width / 130))
    local header_height = math.max(px(44), math.floor(height * .09))
    local composer_height = math.max(px(40), math.floor(height * .07))
    local status_height = (state.status or "") ~= "" and math.max(px(14), math.floor(height * .03)) or 0
    local composer_y = height - margin - composer_height
    local cell = math.max(px(38), math.floor(width / 9))
    local columns = math.max(3, math.floor((width - 2 * margin - cell) / cell))
    local rows = height >= 420 and 3 or 2
    local per_page = columns * rows
    local panel_height = state.emoji_open and (rows * cell + 2 * gap) or 0
    local panel_y = composer_y - gap - panel_height
    local message_y = header_height + status_height + gap
    local message_end = (state.emoji_open and panel_y or composer_y) - gap
    local message_area = math.max(1, message_end - message_y)

    local visible, capacity, used, normalized = UI.visibleRows(messages, state[scroll_key] or 0, message_area, gap, function(message, max_height, index)
        return UI.messageRow(state, context, message, messages[index - 1], mode, width, margin, max_height)
    end)
    state[scroll_key] = normalized

    local elements = {
        FrameContainer:new{ width = width, height = height, padding = 0, bordersize = 0, background = WA.wallpaper, emptySizedWidget(width, height) },
    }
    local actions, back
    if public then
        actions = {
            { icon = "refresh", callback = function() fetchMessages(state, context) end },
            { icon = "more", callback = function() UI.showMenu({ { text = _("Settings"), callback = function() UI.goSettings(state, context) end } }, _("AppDock Lounge")) end },
        }
    else
        actions = {
            { icon = "refresh", callback = function()
                UIManager:scheduleIn(0.1, function()
                    if state.view ~= "dm_conversation" or state.store.selected_recipient_id == "" then return end
                    clearAttachmentFiles(state)
                    fetchConversation(state, context)
                end)
            end },
            { icon = "more", callback = function()
                local items = {
                    { text = _("Delete chat"), callback = function() confirmDeleteConversation(state, context) end },
                    { text = _("Remove contact"), callback = function() confirmRemoveRecipient(state, context, recipient) end },
                    { text = _("Settings"), callback = function() UI.goSettings(state, context) end },
                }
                if not UI.showMenu(items, recipient.displayName) then confirmDeleteConversation(state, context) end
            end },
        }
    end
    if compact then
        back = function() state.compact_sidebar = true; state.view = "dm"; refresh(context) end
    end
    UI.header(elements, context, width, {
        height = header_height, margin = margin, back = back, actions = actions,
        title = public and _("AppDock Lounge") or recipient.displayName,
        subtitle = public and _("Public room · visible to everyone") or (state.loading and _("Updating…") or _("Private chat")),
        avatar_name = public and _("Lounge") or recipient.displayName,
        avatar_color = public and WA.send or UI.nameColor(recipient.displayName),
    })
    if status_height > 0 then
        elements[#elements + 1] = TextWidget:new{ text = state.status, face = Font:getFace("smallinfofont", math.max(px(7), math.floor(status_height * .5))), fgcolor = WA.sub, max_width = width - 2 * margin, overlap_offset = { margin, header_height + 2 } }
    end

    if #messages == 0 then
        elements[#elements + 1] = TextBoxWidget:new{
            bgcolor = WA.wallpaper,
            text = public and _("No public messages cached. Tap refresh to load the lounge.") or _("No private messages yet. Write a message below to start this conversation."),
            face = Font:getFace("smallinfofont", math.max(px(8), math.floor(height * .024))),
            width = width - 4 * margin, alignment = "center", fgcolor = WA.sub,
            overlap_offset = { 2 * margin, message_y + px(20) },
        }
    else
        local y = message_end - used
        for _, item in ipairs(visible) do
            item.row.overlap_offset = { 0, y }
            elements[#elements + 1] = item.row
            y = y + item.row.height + gap
        end
        local scrollbar, scrollbar_offset = buildScrollbar(#messages, state[scroll_key] or 0, capacity, message_end - message_y, width - px(5), message_y, palette, px)
        if scrollbar then scrollbar.overlap_offset = scrollbar_offset; elements[#elements + 1] = scrollbar end
    end

    if state.emoji_open then
        local pages = math.max(1, math.ceil(#ASSETS.order / per_page))
        state.emoji_page = clamp(state.emoji_page or 1, 1, pages)
        elements[#elements + 1] = FrameContainer:new{ width = width, height = panel_height, padding = 0, bordersize = 0, background = WA.panel, emptySizedWidget(width, panel_height), overlap_offset = { 0, panel_y } }
        local start = (state.emoji_page - 1) * per_page
        for slot = 0, per_page - 1 do
            local key = ASSETS.order[start + slot + 1]
            if not key then break end
            elements[#elements + 1] = ActionButton:new{
                width = cell, height = cell, emoji = key, icon_size = math.floor(cell * .66), transparent = true, radius = 0,
                callback = function() UI.insertEmoji(state, mode, key); refresh(context) end,
                overlap_offset = { margin + (slot % columns) * cell, panel_y + gap + math.floor(slot / columns) * cell },
            }
        end
        local nav_height = math.floor((panel_height - 2 * gap) / 2)
        elements[#elements + 1] = ActionButton:new{ width = cell, height = nav_height, title = "‹", bold = true, transparent = true, radius = 0, button_foreground = state.emoji_page > 1 and WA.text or WA.sub,
            callback = function() state.emoji_page = math.max(1, state.emoji_page - 1); refresh(context) end,
            overlap_offset = { width - margin - cell, panel_y + gap } }
        elements[#elements + 1] = ActionButton:new{ width = cell, height = nav_height, title = "›", bold = true, transparent = true, radius = 0, button_foreground = state.emoji_page < pages and WA.text or WA.sub,
            callback = function() state.emoji_page = math.min(pages, state.emoji_page + 1); refresh(context) end,
            overlap_offset = { width - margin - cell, panel_y + gap + nav_height } }
    end

    local draft = public and (state.public_draft or "") or (state.draft_text or "")
    local send_size = composer_height
    local field_width = width - 2 * margin - gap - send_size
    local icon_width = composer_height
    local attach_width = public and 0 or icon_width
    local text_width = field_width - icon_width - attach_width
    elements[#elements + 1] = FrameContainer:new{ width = field_width, height = composer_height, padding = 0, bordersize = 0, radius = math.floor(composer_height / 2), background = WA.white, emptySizedWidget(field_width, composer_height), overlap_offset = { margin, composer_y } }
    elements[#elements + 1] = ActionButton:new{ width = icon_width, height = composer_height, icon = state.emoji_open and "smile_on" or "smile", icon_size = math.floor(composer_height * .52), transparent = true, radius = 0,
        callback = function() state.emoji_open = not state.emoji_open; refresh(context) end,
        overlap_offset = { margin, composer_y } }
    elements[#elements + 1] = ActionButton:new{ width = text_width, height = composer_height, title = draft ~= "" and UI.preview(draft, 70) or _("Message"), align = "left", transparent = true, radius = 0,
        font_size = math.max(px(9), math.floor(composer_height * .24)), button_foreground = draft ~= "" and WA.text or WA.sub,
        callback = function() if public then promptMessage(state, context) else promptDirectMessage(state, context) end end,
        overlap_offset = { margin + icon_width, composer_y } }
    if not public then
        elements[#elements + 1] = ActionButton:new{ width = attach_width, height = composer_height, icon = "plus", icon_size = math.floor(composer_height * .5), transparent = true, radius = 0,
            callback = function() chooseImageAttachment(state, context) end,
            overlap_offset = { margin + icon_width + text_width, composer_y } }
    end
    elements[#elements + 1] = ActionButton:new{ width = send_size, height = send_size, icon = "send", icon_size = math.floor(send_size * .5), button_background = WA.send, radius = math.floor(send_size / 2),
        callback = function()
            if public then
                if (state.public_draft or "") ~= "" then sendMessage(state, context, state.public_draft) else promptMessage(state, context) end
            else
                if (state.draft_text or "") ~= "" then sendDirectMessage(state, context, state.draft_text, nil) else promptDirectMessage(state, context) end
            end
        end,
        overlap_offset = { margin + field_width + gap, composer_y } }

    return SwipeSurface:new{
        width = width,
        height = height,
        content = OverlapGroup:new{ dimen = Geom:new{ w = width, h = height }, allow_mirroring = false, unpack(elements) },
        on_swipe = function(direction) return scrollCollection(state, scroll_key, #messages, capacity, direction, context) end,
    }
end

local function buildTinyChatPane(state, context, mode)
    local palette = active_palette
    local width, height = context.dimen.w, context.dimen.h
    local px = context.px or scale
    local margin, gap = math.max(px(2), math.floor(width / 90)), math.max(1, px(2))
    local header_height = math.max(px(19), math.floor(height * .18))
    local button_height = math.max(px(20), math.floor(height * .19))
    local title_width = width - 2 * margin - math.max(px(30), math.floor(width * .21)) - gap
    local settings_width = width - 2 * margin - title_width - gap
    local elements = {
        FrameContainer:new{ width = width, height = height, padding = 0, bordersize = 0, background = palette.background, emptySizedWidget(width, height) },
        FrameContainer:new{ width = width, height = header_height, padding = 0, bordersize = 0, background = palette.secondary, emptySizedWidget(width, header_height) },
    }

    local function addHeader(title)
        elements[#elements + 1] = TextWidget:new{ text = title, face = Font:getFace("smallinfofont", math.max(px(8), math.floor(header_height * .43))), fgcolor = palette.on_secondary, bold = true, max_width = title_width, overlap_offset = { margin, math.max(1, math.floor(header_height * .24)) } }
        elements[#elements + 1] = ActionButton:new{ width = settings_width, height = header_height - 2 * margin, title = _("Settings"), button_background = palette.tertiary, button_foreground = palette.on_tertiary, callback = function() state.view = "settings"; refresh(context) end, overlap_offset = { width - margin - settings_width, margin } }
    end

    if mode == "timeline" then
        addHeader(_("Public Lounge"))
        local composer_y = height - margin - button_height
        local content_y, content_end = header_height + gap, composer_y - gap
        local first, last, normalized = visibleRecentRange(state.store.messages or {}, state.public_scroll or 0, 1)
        state.public_scroll = normalized
        if last >= first then
            local message = state.store.messages[last]
            elements[#elements + 1] = ActionButton:new{ width = width - 2 * margin, height = math.max(px(25), content_end - content_y), body = dmPreview(message.authorName .. ": " .. message.body, 84), button_background = palette.surface, button_foreground = palette.on_surface, callback = function() state.selected_id = message.id; state.view = "message"; refresh(context) end, overlap_offset = { margin, content_y } }
        else
            elements[#elements + 1] = TextWidget:new{ text = _("No messages"), face = Font:getFace("smallinfofont", px(8)), fgcolor = palette.on_variant, max_width = width - 2 * margin, overlap_offset = { margin, content_y } }
        end
        local send_width = math.max(px(36), math.floor((width - 2 * margin - gap) * .27))
        local field_width = width - 2 * margin - gap - send_width
        elements[#elements + 1] = ActionButton:new{ width = field_width, height = button_height, title = state.public_draft ~= "" and dmPreview(state.public_draft, 26) or _("Write…"), button_background = palette.surface, button_foreground = palette.on_variant, callback = function() promptMessage(state, context) end, overlap_offset = { margin, composer_y } }
        elements[#elements + 1] = ActionButton:new{ width = send_width, height = button_height, title = _("Send"), primary = true, callback = function() if state.public_draft ~= "" then sendMessage(state, context, state.public_draft) else promptMessage(state, context) end end, overlap_offset = { margin + field_width + gap, composer_y } }
        return SwipeSurface:new{ width = width, height = height, content = OverlapGroup:new{ dimen = Geom:new{ w = width, h = height }, allow_mirroring = false, unpack(elements) }, on_swipe = function(direction) return scrollCollection(state, "public_scroll", #(state.store.messages or {}), 1, direction, context) end }
    end

    local recipient = selectedRecipient(state)
    if recipient and not state.compact_sidebar then
        addHeader(recipient.displayName)
        local composer_y = height - margin - button_height
        local content_y, content_end = header_height + gap, composer_y - gap
        local messages = state.store.dm_messages or {}
        local first, last, normalized = visibleRecentRange(messages, state.dm_scroll or 0, 1)
        state.dm_scroll = normalized
        if last >= first then
            local message = messages[last]
            local own = message.senderDeviceId == state.store.device_id or (message.senderDeviceId == "" and message.authorName == state.store.display_name)
            elements[#elements + 1] = ActionButton:new{ width = width - 2 * margin, height = math.max(px(25), content_end - content_y), body = dmPreview(directBubbleText(message, own), 84), button_background = own and palette.primary or palette.tertiary, button_foreground = own and palette.on_primary or palette.on_tertiary, callback = function() state.selected_dm_id = message.id; state.view = "dm_message"; refresh(context) end, overlap_offset = { margin, content_y } }
        else
            elements[#elements + 1] = TextWidget:new{ text = _("No private messages"), face = Font:getFace("smallinfofont", px(8)), fgcolor = palette.on_variant, max_width = width - 2 * margin, overlap_offset = { margin, content_y } }
        end
        local available = width - 2 * margin - 2 * gap
        local field_width = math.max(px(54), math.floor(available * .55))
        local attach_width = math.max(px(23), math.floor(available * .18))
        local send_width = available - field_width - attach_width
        elements[#elements + 1] = ActionButton:new{ width = field_width, height = button_height, title = state.draft_text ~= "" and dmPreview(state.draft_text, 24) or _("Write…"), button_background = palette.surface, button_foreground = palette.on_variant, callback = function() promptDirectMessage(state, context) end, overlap_offset = { margin, composer_y } }
        elements[#elements + 1] = ActionButton:new{ width = attach_width, height = button_height, title = _("+") , button_background = palette.tertiary, button_foreground = palette.on_tertiary, callback = function() chooseImageAttachment(state, context) end, overlap_offset = { margin + field_width + gap, composer_y } }
        elements[#elements + 1] = ActionButton:new{ width = send_width, height = button_height, title = _("Send"), primary = true, callback = function() if state.draft_text ~= "" then sendDirectMessage(state, context, state.draft_text, nil) else promptDirectMessage(state, context) end end, overlap_offset = { margin + field_width + gap + attach_width + gap, composer_y } }
        return SwipeSurface:new{ width = width, height = height, content = OverlapGroup:new{ dimen = Geom:new{ w = width, h = height }, allow_mirroring = false, unpack(elements) }, on_swipe = function(direction) return scrollCollection(state, "dm_scroll", #messages, 1, direction, context) end }
    end

    addHeader(_("Chats"))
    local controls_y = header_height + gap
    local control_width = math.floor((width - 2 * margin - 2 * gap) / 3)
    elements[#elements + 1] = ActionButton:new{ width = control_width, height = button_height, title = _("Public"), primary = state.view == "timeline", callback = function() state.compact_sidebar = false; state.view = "timeline"; refresh(context) end, overlap_offset = { margin, controls_y } }
    elements[#elements + 1] = ActionButton:new{ width = control_width, height = button_height, title = _("Find"), button_background = palette.tertiary, button_foreground = palette.on_tertiary, callback = function() promptRecipientSearch(state, context) end, overlap_offset = { margin + control_width + gap, controls_y } }
    elements[#elements + 1] = ActionButton:new{ width = control_width, height = button_height, title = "↻", primary = true, callback = function() fetchRecipients(state, context, "") end, overlap_offset = { margin + 2 * (control_width + gap), controls_y } }
    local list_y, list_end = controls_y + button_height + gap, height - margin
    local row_height = math.max(px(23), math.floor(math.max(0, list_end - list_y) / 2))
    local capacity = math.max(1, math.floor(math.max(0, list_end - list_y) / (row_height + gap)))
    local first, last, normalized = visibleTopRange(state.store.recipients or {}, state.recipient_scroll or 0, capacity)
    state.recipient_scroll = normalized
    if last < first then
        elements[#elements + 1] = TextWidget:new{ text = _("No contacts"), face = Font:getFace("smallinfofont", px(8)), fgcolor = palette.on_variant, max_width = width - 2 * margin, overlap_offset = { margin, list_y } }
    else
        local y = list_y
        for index = first, last do
            local contact = state.store.recipients[index]
            local remove_width = math.max(px(20), math.floor((width - 2 * margin) * .15))
            local row_width = width - 2 * margin - gap - remove_width
            elements[#elements + 1] = ActionButton:new{ width = row_width, height = row_height, title = dmPreview(contact.displayName, 22), primary = contact.deviceId == state.store.selected_recipient_id, callback = function()
                clearAttachmentFiles(state)
                state.store.selected_recipient_id, state.store.selected_recipient_name = contact.deviceId, contact.displayName
                state.compact_sidebar, state.view, state.dm_scroll = false, "dm_conversation", 0
                saveStore(state.store)
                fetchConversation(state, context)
            end, overlap_offset = { margin, y } }
            elements[#elements + 1] = ActionButton:new{ width = remove_width, height = row_height, title = "×", button_background = palette.surface_variant, button_foreground = palette.on_variant, callback = function() confirmRemoveRecipient(state, context, contact) end, overlap_offset = { margin + row_width + gap, y } }
            y = y + row_height + gap
        end
    end
    return SwipeSurface:new{ width = width, height = height, content = OverlapGroup:new{ dimen = Geom:new{ w = width, h = height }, allow_mirroring = false, unpack(elements) }, on_swipe = function(direction) return scrollCollection(state, "recipient_scroll", #(state.store.recipients or {}), capacity, direction, context) end }
end

local function tinySettingsPane(instance, context)
    local state = stateFor(instance)
    active_palette = themePalette(context)
    active_px = context.px or scale
    local palette = active_palette
    local width, height = context.dimen.w, context.dimen.h
    local px = context.px or scale
    local margin, gap = math.max(px(2), math.floor(width / 90)), math.max(1, px(2))
    local header_height = math.max(px(19), math.floor(height * .18))
    local button_height = math.max(px(20), math.floor((height - header_height - 2 * margin - 3 * gap) / 4))
    local y = header_height + gap
    local elements = {
        FrameContainer:new{ width = width, height = height, padding = 0, bordersize = 0, background = palette.background, emptySizedWidget(width, height) },
        FrameContainer:new{ width = width, height = header_height, padding = 0, bordersize = 0, background = palette.secondary, emptySizedWidget(width, header_height) },
        TextWidget:new{ text = _("Settings"), face = Font:getFace("smallinfofont", math.max(px(8), math.floor(header_height * .43))), fgcolor = palette.on_secondary, bold = true, max_width = width - 2 * margin, overlap_offset = { margin, math.max(1, math.floor(header_height * .24)) } },
        ActionButton:new{ width = width - 2 * margin, height = button_height, title = _("Public address"), button_background = palette.surface_variant, button_foreground = palette.on_variant, callback = function() setEndpoint(state, context) end, overlap_offset = { margin, y } },
        ActionButton:new{ width = width - 2 * margin, height = button_height, title = _("DM address"), primary = true, callback = function() setDMEndpoint(state, context) end, overlap_offset = { margin, y + button_height + gap } },
        ActionButton:new{ width = width - 2 * margin, height = button_height, title = hasIdentity(state.store) and _("Reset identity") or _("Create identity"), callback = function() createOrResetIdentity(state, context) end, overlap_offset = { margin, y + 2 * (button_height + gap) } },
        ActionButton:new{ width = width - 2 * margin, height = button_height, title = _("‹ Chats"), button_background = palette.tertiary, button_foreground = palette.on_tertiary, callback = function() state.compact_sidebar = true; state.view = "dm"; refresh(context) end, overlap_offset = { margin, y + 3 * (button_height + gap) } },
    }
    return OverlapGroup:new{ dimen = Geom:new{ w = width, h = height }, allow_mirroring = false, unpack(elements) }
end

local function chatWorkspacePane(instance, context, mode)
    local state = stateFor(instance)
    active_palette = themePalette(context)
    active_px = context.px or scale
    local width, height = context.dimen.w, context.dimen.h
    local px = context.px or scale
    local split_minimum = math.max(px(420), 360)
    if width < px(300) or height < px(220) then return buildTinyChatPane(state, context, mode) end
    local compact = width < split_minimum
    if compact then
        if mode == "timeline" then return UI.buildChatPanel(state, context, width, height, true, "public") end
        if selectedRecipient(state) and not state.compact_sidebar then return UI.buildChatPanel(state, context, width, height, true, "dm") end
        return UI.buildSidebar(state, context, width, height, false)
    end
    if mode ~= "timeline" and selectedRecipient(state) and state.view == "dm" then state.view = "dm_conversation" end
    local margin, gap = math.max(px(6), math.floor(width / 110)), math.max(px(5), math.floor(width / 160))
    local sidebar_width = clamp(math.floor(width * .32), px(178), math.floor(width * .42))
    local content_width = width - 2 * margin - gap - sidebar_width
    local lounge = mode == "timeline" or not selectedRecipient(state)
    local sidebar = UI.buildSidebar(state, context, sidebar_width, height - 2 * margin, true)
    local content = UI.buildChatPanel(state, context, content_width, height - 2 * margin, false, lounge and "public" or "dm")
    sidebar.overlap_offset = { margin, margin }
    content.overlap_offset = { margin + sidebar_width + gap, margin }
    return OverlapGroup:new{
        dimen = Geom:new{ w = width, h = height },
        allow_mirroring = false,
        FrameContainer:new{ width = width, height = height, padding = 0, bordersize = 0, background = WA.wallpaper, emptySizedWidget(width, height) },
        sidebar,
        content,
    }
end

local function timelinePane(instance, context)
    return chatWorkspacePane(instance, context, "timeline")
end

local function settingsPane(instance, context)
    local state = stateFor(instance)
